const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"backend/src/services/paystack.service.ts":"/**\n * DropOS Paystack Service\n * \n * HOW PAYMENTS WORK:\n * 1. Merchant enters their bank account details in Settings → Payments\n * 2. We call Paystack API to verify the account name and create a Subaccount\n * 3. We store the paystackSubCode on the store\n * 4. When a customer pays, Paystack automatically splits:\n *    - 98% goes to merchant's bank account (via their subaccount)\n *    - 2%  stays in DropOS's Paystack account (platform commission)\n * 5. Merchant never needs their own Paystack account\n */\n\nimport axios from \"axios\";\nimport { prisma } from \"../config/database\";\n\nconst BASE    = \"https://api.paystack.co\";\nconst HEADERS = {\n  Authorization: `Bearer ${process.env.PAYSTACK_SECRET_KEY}`,\n  \"Content-Type\": \"application/json\",\n};\n\nconst PLATFORM_FEE_PERCENT = 2; // DropOS takes 2% of every transaction\n\n// ── Verify a Nigerian bank account ──────────────────────────────────────────\nexport async function verifyBankAccount(accountNumber: string, bankCode: string) {\n  const { data } = await axios.get(\n    `${BASE}/bank/resolve?account_number=${accountNumber}&bank_code=${bankCode}`,\n    { headers: HEADERS }\n  );\n  return {\n    accountName:   data.data.account_name,\n    accountNumber: data.data.account_number,\n  };\n}\n\n// ── Get all Nigerian banks ───────────────────────────────────────────────────\nexport async function getNigerianBanks(): Promise<{ name: string; code: string }[]> {\n  try {\n    const { data } = await axios.get(`${BASE}/bank?country=nigeria&perPage=100`, { headers: HEADERS });\n    return data.data.map((b: any) => ({ name: b.name, code: b.code }));\n  } catch {\n    // Return common banks as fallback\n    return [\n      { name:\"Access Bank\",         code:\"044\" },\n      { name:\"Citibank\",            code:\"023\" },\n      { name:\"Ecobank\",             code:\"050\" },\n      { name:\"Fidelity Bank\",       code:\"070\" },\n      { name:\"First Bank\",          code:\"011\" },\n      { name:\"First City Monument Bank (FCMB)\", code:\"214\" },\n      { name:\"GTBank\",              code:\"058\" },\n      { name:\"Heritage Bank\",       code:\"030\" },\n      { name:\"Keystone Bank\",       code:\"082\" },\n      { name:\"Kuda Bank\",           code:\"090267\" },\n      { name:\"Opay\",                code:\"999992\" },\n      { name:\"Palmpay\",             code:\"999991\" },\n      { name:\"Polaris Bank\",        code:\"076\" },\n      { name:\"Providus Bank\",       code:\"101\" },\n      { name:\"Stanbic IBTC\",        code:\"221\" },\n      { name:\"Standard Chartered\",  code:\"068\" },\n      { name:\"Sterling Bank\",       code:\"232\" },\n      { name:\"Union Bank\",          code:\"032\" },\n      { name:\"United Bank for Africa (UBA)\", code:\"033\" },\n      { name:\"Unity Bank\",          code:\"215\" },\n      { name:\"VFD Microfinance Bank\", code:\"566\" },\n      { name:\"Wema Bank\",           code:\"035\" },\n      { name:\"Zenith Bank\",         code:\"057\" },\n    ];\n  }\n}\n\n// ── Create Paystack Subaccount for a merchant ────────────────────────────────\n// This is called once when merchant saves their bank details\nexport async function createSubaccount(params: {\n  storeId:       string;\n  businessName:  string;\n  bankCode:      string;\n  accountNumber: string;\n}): Promise<string> { // returns subaccount code\n  const { data } = await axios.post(\n    `${BASE}/subaccount`,\n    {\n      business_name:            params.businessName,\n      bank_code:                params.bankCode,\n      account_number:           params.accountNumber,\n      percentage_charge:        PLATFORM_FEE_PERCENT, // DropOS takes 2%\n      description:              `DropOS merchant: ${params.businessName}`,\n      settlement_bank:          params.bankCode,\n      settlement_schedule:      \"auto\", // Paystack settles merchant automatically\n    },\n    { headers: HEADERS }\n  );\n\n  const subCode = data.data.subaccount_code;\n\n  // Save to store\n  await prisma.store.update({\n    where: { id: params.storeId },\n    data:  {\n      paystackSubCode:   subCode,\n      paystackConnected: true,\n    } as any,\n  });\n\n  return subCode;\n}\n\n// ── Initialize a split payment ────────────────────────────────────────────────\n// 98% → merchant's bank, 2% → DropOS\nexport async function initializeSplitPayment(params: {\n  amount:         number; // in NGN (not kobo)\n  email:          string; // customer email\n  orderId:        string;\n  storeId:        string;\n  callbackUrl:    string;\n  subaccountCode: string; // merchant's Paystack subaccount\n  currency?:      string;\n}) {\n  const amountKobo = Math.round(params.amount * 100);\n\n  const body: any = {\n    amount:       amountKobo,\n    email:        params.email,\n    currency:     params.currency || \"NGN\",\n    callback_url: params.callbackUrl,\n    metadata: {\n      orderId: params.orderId,\n      storeId: params.storeId,\n    },\n    subaccount:   params.subaccountCode,\n    bearer:       \"subaccount\", // subaccount bears Paystack fees\n    // DropOS keeps 2% — Paystack calculates this automatically\n  };\n\n  const { data } = await axios.post(`${BASE}/transaction/initialize`, body, { headers: HEADERS });\n  return {\n    authorizationUrl: data.data.authorization_url,\n    reference:        data.data.reference,\n    accessCode:       data.data.access_code,\n  };\n}\n\n// ── Verify a transaction ──────────────────────────────────────────────────────\nexport async function verifyTransaction(reference: string) {\n  const { data } = await axios.get(`${BASE}/transaction/verify/${reference}`, { headers: HEADERS });\n  return {\n    status:    data.data.status,          // \"success\" | \"failed\"\n    amount:    data.data.amount / 100,    // back to NGN\n    reference: data.data.reference,\n    paidAt:    data.data.paid_at,\n    channel:   data.data.channel,         // \"card\" | \"bank\" | \"ussd\"\n    customer:  data.data.customer,\n  };\n}\n\n// ── Verify Paystack webhook signature ─────────────────────────────────────────\nexport function verifyWebhookSignature(payload: string, signature: string): boolean {\n  const crypto = require(\"crypto\");\n  const hash   = crypto\n    .createHmac(\"sha512\", process.env.PAYSTACK_SECRET_KEY!)\n    .update(payload)\n    .digest(\"hex\");\n  return hash === signature;\n}\n","backend/src/controllers/bankAccount.controller.ts":"import { Request, Response } from \"express\";\nimport { prisma } from \"../config/database\";\nimport { verifyBankAccount, getNigerianBanks, createSubaccount } from \"../services/paystack.service\";\nimport { AppError } from \"../utils/AppError\";\n\n// GET /api/banks — list all Nigerian banks\nexport const listBanks = async (_req: Request, res: Response) => {\n  const banks = await getNigerianBanks();\n  return res.json({ success: true, data: banks });\n};\n\n// POST /api/stores/:storeId/bank/verify — verify account name before saving\nexport const verifyAccount = async (req: Request, res: Response) => {\n  const { accountNumber, bankCode } = req.body;\n  if (!accountNumber || !bankCode)\n    throw new AppError(\"accountNumber and bankCode required\", 400);\n\n  const result = await verifyBankAccount(accountNumber, bankCode);\n  return res.json({ success: true, data: result });\n};\n\n// POST /api/stores/:storeId/bank/connect — save bank + create Paystack subaccount\nexport const connectBankAccount = async (req: Request, res: Response) => {\n  const { storeId }  = req.params;\n  const { bankCode, bankName, accountNumber, accountName } = req.body;\n\n  if (!bankCode || !accountNumber || !accountName)\n    throw new AppError(\"bankCode, accountNumber, accountName required\", 400);\n\n  const store = await prisma.store.findUnique({\n    where:  { id: storeId },\n    select: { name: true, ownerId: true },\n  });\n  if (!store) throw new AppError(\"Store not found\", 404);\n\n  // Create or update the Paystack subaccount\n  let subCode: string;\n  try {\n    subCode = await createSubaccount({\n      storeId,\n      businessName:  store.name,\n      bankCode,\n      accountNumber,\n    });\n  } catch (e: any) {\n    // If Paystack key not set, save bank details anyway for future use\n    console.error(\"Paystack subaccount creation failed:\", e.message);\n    subCode = \"\";\n  }\n\n  // Save bank details to store\n  await prisma.store.update({\n    where: { id: storeId },\n    data: {\n      bankName,\n      bankCode,\n      accountNumber,\n      accountName,\n      paystackSubCode:   subCode || undefined,\n      paystackConnected: !!subCode,\n    } as any,\n  });\n\n  return res.json({\n    success: true,\n    message: subCode\n      ? \"Bank account connected. You will receive 98% of every sale directly to this account.\"\n      : \"Bank details saved. Payment routing will activate once configured.\",\n    data: { accountName, accountNumber, bankName, connected: !!subCode },\n  });\n};\n\n// GET /api/stores/:storeId/bank — get current bank info\nexport const getBankInfo = async (req: Request, res: Response) => {\n  const store = await prisma.store.findUnique({\n    where:  { id: req.params.storeId },\n    select: {\n      bankName:          true,\n      accountNumber:     true,\n      accountName:       true,\n      paystackConnected: true,\n      paystackSubCode:   true,\n    } as any,\n  });\n  if (!store) throw new AppError(\"Store not found\", 404);\n\n  return res.json({\n    success: true,\n    data: {\n      bankName:      (store as any).bankName || null,\n      // Mask account number — show only last 4 digits\n      accountNumber: (store as any).accountNumber\n        ? `****${(store as any).accountNumber.slice(-4)}`\n        : null,\n      accountName:      (store as any).accountName || null,\n      paystackConnected:(store as any).paystackConnected || false,\n    },\n  });\n};\n","backend/src/controllers/payment.controller.ts":"// src/controllers/payment.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { calculateFee, detectGateway } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport {\n  createStripePaymentIntent, constructStripeEvent,\n  initializePaystack, verifyPaystack, verifyPaystackWebhook,\n  initializeFlutterwave, verifyFlutterwave, verifyFlutterwaveWebhook,\n} from \"../services/payment.service\";\nimport { emailService } from \"../services/email.service\";\nimport { logger } from \"../utils/logger\";\n\n// ── Initialize Payment ────────────────────────────────────────────────────────\nexport const initializePayment = async (req: Request, res: Response) => {\n  const schema = z.object({\n    orderId:   z.string().uuid(),\n    gateway:   z.enum([\"STRIPE\",\"PAYSTACK\",\"FLUTTERWAVE\"]).optional(),\n    country:   z.string().optional(),\n  });\n  const { orderId, gateway: manualGateway, country } = schema.parse(req.body);\n\n  const order = await prisma.order.findUnique({\n    where: { id: orderId },\n    include: { store: true },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  if ((order as any).payment) throw new AppError(\"Payment already initiated for this order\", 400);\n\n  // Auto-detect gateway\n  const gateway = manualGateway || detectGateway(country);\n\n  const feePercent = await getPlatformFee();\n  const { platformFee, storeEarnings } = calculateFee(order.total, feePercent);\n\n  const frontendUrl = process.env.FRONTEND_URL || \"http://localhost:3000\";\n  const storeSlug   = order.store?.slug || \"\";\n  // Correct callback URL: points to the actual payment/callback page with real orderId\n  const callbackUrl = `${frontendUrl}/store/${storeSlug}/payment/callback?orderId=${orderId}`;\n\n  let initData: any = {};\n\n  if (gateway === \"STRIPE\") {\n    initData = await createStripePaymentIntent({\n      amount:        order.total,\n      currency:      order.currency,\n      orderId:       order.id,\n      storeId:       order.storeId,\n      customerEmail: order.customerEmail,\n    });\n  } else if (gateway === \"PAYSTACK\") {\n    const subaccountCode = (order.store as any)?.paystackSubCode || null;\n\n    if (subaccountCode) {\n      // Merchant has connected bank → 98% to merchant's bank, 2% to DropOS\n      const { initializeSplitPayment } = await import(\"../services/paystack.service\");\n      initData = await initializeSplitPayment({\n        amount:         order.total,\n        email:          order.customerEmail,\n        orderId:        order.id,\n        storeId:        order.storeId,\n        callbackUrl,\n        subaccountCode,\n        currency:       order.currency === \"NGN\" ? \"NGN\" : \"NGN\",\n      });\n    } else {\n      // No bank connected yet — all goes to DropOS until merchant sets up bank\n      initData = await initializePaystack({\n        amount:      order.total,\n        currency:    order.currency === \"NGN\" ? \"NGN\" : \"NGN\",\n        email:       order.customerEmail,\n        orderId:     order.id,\n        storeId:     order.storeId,\n        callbackUrl,\n      });\n    }\n  } else if (gateway === \"FLUTTERWAVE\") {\n    initData = await initializeFlutterwave({\n      amount:      order.total,\n      currency:    order.currency,\n      email:       order.customerEmail,\n      name:        order.customerName,\n      phone:       order.customerPhone || undefined,\n      orderId:     order.id,\n      storeId:     order.storeId,\n      redirectUrl: callbackUrl,\n    });\n  }\n\n  // Create pending payment record\n  await (prisma.payment as any).create({\n    data: {\n      orderId,\n      storeId:           order.storeId,\n      gateway:           gateway as any,\n      amount:            order.total,\n      currency:          order.currency,\n      platformFee,\n      platformFeePercent: feePercent,\n      storeEarnings,\n      status:            \"PENDING\",\n      metadata:          initData,\n    },\n  });\n\n  return res.json({\n    success: true,\n    data: { gateway, ...initData, amount: order.total, currency: order.currency },\n  });\n};\n\n// ── Stripe Webhook ────────────────────────────────────────────────────────────\nexport const stripeWebhook = async (req: Request, res: Response) => {\n  const sig = req.headers[\"stripe-signature\"] as string;\n  const event = constructStripeEvent(req.body as Buffer, sig);\n\n  if (event.type === \"payment_intent.succeeded\") {\n    const intent = event.data.object as any;\n    const orderId = intent.metadata?.orderId;\n    if (orderId) await completePayment(orderId, intent.id, \"STRIPE\");\n  }\n\n  if (event.type === \"payment_intent.payment_failed\") {\n    const intent = event.data.object as any;\n    const orderId = intent.metadata?.orderId;\n    if (orderId) await failPayment(orderId, \"STRIPE\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Paystack Webhook ──────────────────────────────────────────────────────────\nexport const paystackWebhook = async (req: Request, res: Response) => {\n  const sig     = req.headers[\"x-paystack-signature\"] as string;\n  const payload = (req.body as Buffer).toString();\n\n  if (!verifyPaystackWebhook(payload, sig)) {\n    throw new AppError(\"Invalid webhook signature\", 400);\n  }\n\n  let event: any;\n  try { event = JSON.parse(payload); } catch { return res.json({ received: true }); }\n\n  if (event.event === \"charge.success\") {\n    const orderId = event.data?.metadata?.orderId;\n    if (orderId) await completePayment(orderId, event.data.reference, \"PAYSTACK\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Flutterwave Webhook ───────────────────────────────────────────────────────\nexport const flutterwaveWebhook = async (req: Request, res: Response) => {\n  const sig     = req.headers[\"verif-hash\"] as string;\n  const payload = (req.body as Buffer).toString();\n\n  if (sig !== process.env.FLUTTERWAVE_SECRET_KEY) {\n    throw new AppError(\"Invalid webhook signature\", 400);\n  }\n\n  let event: any;\n  try { event = JSON.parse(payload); } catch { return res.json({ received: true }); }\n\n  if (event.status === \"successful\") {\n    const orderId = event.meta?.orderId;\n    if (orderId) await completePayment(orderId, String(event.id), \"FLUTTERWAVE\");\n  }\n\n  return res.json({ received: true });\n};\n\n// ── Verify Payment (after redirect) ──────────────────────────────────────────\nexport const verifyPayment = async (req: Request, res: Response) => {\n  const { orderId, reference, transaction_id } = req.query;\n  if (!orderId) throw new AppError(\"orderId required\", 400);\n\n  const payment = await prisma.payment.findUnique({ where: { orderId: orderId as string } });\n  if (!payment) throw new AppError(\"Payment not found\", 404);\n\n  if (payment.status === \"SUCCESS\") {\n    return res.json({ success: true, data: { status: \"SUCCESS\", payment } });\n  }\n\n  // Verify with gateway\n  if (payment.gateway === \"PAYSTACK\" && reference) {\n    const result = await verifyPaystack(reference as string);\n    if (result.status === \"success\") {\n      await completePayment(orderId as string, result.reference, \"PAYSTACK\");\n    }\n  }\n\n  if (payment.gateway === \"FLUTTERWAVE\" && transaction_id) {\n    const result = await verifyFlutterwave(transaction_id as string);\n    if (result.status === \"successful\") {\n      await completePayment(orderId as string, String(result.id), \"FLUTTERWAVE\");\n    }\n  }\n\n  const updated = await prisma.payment.findUnique({ where: { orderId: orderId as string } });\n\n  // Return order data alongside payment so the callback page can render the success screen\n  const orderData = await prisma.order.findUnique({\n    where:   { id: orderId as string },\n    include: { items: true, store: { select: { name: true, slug: true, primaryColor: true } } },\n  });\n\n  return res.json({ success: true, data: { ...updated, order: orderData } });\n};\n\n// ── Admin: Get All Payments ───────────────────────────────────────────────────\nexport const getAllPayments = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, status, gateway } = req.query;\n  const take = Math.min(Number(limit), 100);\n  const skip = (Math.max(Number(page), 1) - 1) * take;\n\n  const where: any = {};\n  if (status)  where.status  = status;\n  if (gateway) where.gateway = gateway;\n\n  const [payments, total] = await Promise.all([\n    await prisma.payment.findMany({\n      where, take, skip,\n      include: {\n        order: { select: { orderNumber: true, customerName: true, customerEmail: true } },\n        store: { select: { name: true, owner: { select: { name: true, email: true } } } },\n      },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.payment.count({ where }),\n  ]);\n\n  const totals = await prisma.payment.aggregate({\n    where: { status: \"SUCCESS\" },\n    _sum:  { amount: true, platformFee: true, storeEarnings: true },\n  });\n\n  return res.json({\n    success: true,\n    data: payments,\n    totals: totals._sum,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Helpers ──────────────────────────────────────────────────────────────────\nasync function getPlatformFee(): Promise<number> {\n  const settings = await prisma.platformSettings.findUnique({ where: { id: \"singleton\" } });\n  return settings?.platformFeePercent || Number(process.env.PLATFORM_FEE_PERCENT || 10);\n}\n\nasync function completePayment(orderId: string, reference: string, gateway: string) {\n  try {\n    await prisma.$transaction([\n      prisma.payment.update({\n        where: { orderId },\n        data:  { status: \"SUCCESS\", gatewayReference: reference, paidAt: new Date() },\n      }),\n      prisma.order.update({\n        where: { id: orderId },\n        data:  { status: \"PROCESSING\" },\n      }),\n    ]);\n\n    const order = await prisma.order.findUnique({\n      where: { id: orderId },\n      include: { store: true, items: true },\n    });\n    if (order) {\n      // ── Customer confirmation email (with real line items) ─────────────────\n      await emailService.sendOrderConfirmation({\n        email:       order.customerEmail,\n        name:        order.customerName,\n        orderNumber: order.orderNumber,\n        total:       order.total,\n        currency:    order.currency,\n        storeName:   order.store?.name || \"Store\",\n        storeEmail:  order.store?.supportEmail || undefined,\n        items:       (order.items as any[]).map(i => ({\n          name:     i.name,\n          quantity: i.quantity,\n          price:    i.price,\n        })),\n      });\n\n      // ── Store owner new-order alert ────────────────────────────────────────\n      const owner = await prisma.user.findUnique({\n        where:  { id: order.store!.ownerId },\n        select: { email: true, name: true, phone: true },\n      });\n      if (owner) {\n        emailService.sendNewOrderAlert({\n          ownerEmail:   owner.email,\n          ownerName:    owner.name,\n          orderNumber:  order.orderNumber,\n          customerName: order.customerName,\n          total:        order.total,\n          currency:     order.currency,\n          storeName:    order.store!.name,\n          itemCount:    (order.items as any[]).length,\n        }).catch(() => {/* non-fatal */});\n      }\n\n      // ── Update customer spend stats ────────────────────────────────────────\n      if (order.customerId) {\n        await prisma.storeCustomer.update({\n          where: { id: order.customerId },\n          data: {\n            totalSpent: { increment: order.total },\n            orderCount: { increment: 1 },\n          },\n        });\n      }\n    }\n  } catch (err) {\n    logger.error(\"completePayment error:\", err);\n  }\n}\n\nasync function failPayment(orderId: string, gateway: string) {\n  try {\n    await prisma.payment.update({\n      where: { orderId },\n      data:  { status: \"FAILED\" },\n    });\n    logger.warn(`Payment failed for order ${orderId} via ${gateway}`);\n\n    // Notify customer\n    const order = await prisma.order.findUnique({\n      where:   { id: orderId },\n      include: { store: true },\n    });\n    if (order) {\n      const { emailService } = await import(\"../services/email.service\");\n      emailService.sendPaymentFailed(\n        order.customerEmail,\n        order.customerName,\n        order.orderNumber,\n        `$${order.total.toFixed(2)}`,\n        order.store?.name || \"Store\"\n      );\n    }\n  } catch (err) {\n    logger.error(\"failPayment error:\", err);\n  }\n}\n","backend/src/routes/bank.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { listBanks, verifyAccount, connectBankAccount, getBankInfo } from \"../controllers/bankAccount.controller\";\n\nconst router = Router();\n\nrouter.get  (\"/\",                              listBanks);      // public — no auth needed\nrouter.post (\"/verify\",  authenticate,         verifyAccount);\nrouter.post (\"/:storeId/connect\", authenticate, connectBankAccount);\nrouter.get  (\"/:storeId\",         authenticate, getBankInfo);\n\nexport default router;\n","backend/src/app.ts":"import \"express-async-errors\";\n\nimport express, { Request, Response, NextFunction } from \"express\";\nimport cors from \"cors\";\nimport helmet from \"helmet\";\nimport rateLimit from \"express-rate-limit\";\n\nconst authLimiter = rateLimit({\n  windowMs: 15 * 60 * 1000, // 15 minutes\n  max: 20, // 20 attempts per IP per 15 min\n  message: { success: false, message: \"Too many attempts. Try again in 15 minutes.\" },\n  standardHeaders: true,\n  legacyHeaders: false,\n});\n\nconst uploadLimiter = rateLimit({\n  windowMs: 60 * 1000, // 1 minute\n  max: 30, // 30 uploads per minute\n  message: { success: false, message: \"Upload rate limit reached. Slow down.\" },\n});\nimport compression from \"compression\";\nimport morgan from \"morgan\";\nimport cookieParser from \"cookie-parser\";\nimport path from \"path\";\n\n// Middleware\nimport { globalRateLimiter } from \"./middleware/rateLimiter\";\nimport { errorHandler } from \"./middleware/errorHandler\";\nimport { notFound } from \"./middleware/notFound\";\nimport { requestLogger } from \"./middleware/requestLogger\";\n\n// Core Routes\nimport authRoutes        from \"./routes/auth.routes\";\nimport storeRoutes       from \"./routes/store.routes\";\nimport productRoutes     from \"./routes/product.routes\";\nimport orderRoutes       from \"./routes/order.routes\";\nimport paymentRoutes     from \"./routes/payment.routes\";\nimport customerRoutes    from \"./routes/customer.routes\";\nimport adminRoutes       from \"./routes/admin.routes\";\nimport analyticsRoutes   from \"./routes/analytics.routes\";\nimport uploadRoutes      from \"./routes/upload.routes\";\nimport supportRoutes     from \"./routes/support.routes\";\nimport notificationRoutes from \"./routes/notification.routes\";\nimport couponRoutes      from \"./routes/coupon.routes\";\nimport discountRoutes    from \"./routes/discount.routes\";\nimport affiliateRoutes   from \"./routes/affiliate.routes\";\nimport aiRoutes          from \"./routes/ai.routes\";\nimport pushRoutes        from \"./routes/push.routes\";\nimport shippingRoutes    from \"./routes/shipping.routes\";\nimport reviewRoutes      from \"./routes/review.routes\";\nimport invoiceRoutes     from \"./routes/invoice.routes\";\nimport emailRoutes       from \"./routes/email.routes\";\nimport upsellRoutes      from \"./routes/upsell.routes\";\nimport abandonedCartRoutes from \"./routes/abandonedCart.routes\";\nimport notifSettingsRoutes from \"./routes/notificationSettings.routes\";\nimport virtualAccountRoutes from \"./routes/virtualAccount.routes\";\nimport whatsappRoutes    from \"./routes/whatsapp.routes\";\nimport deliveryRoutes    from \"./routes/delivery.routes\";\nimport currencyRoutes      from \"./routes/currency.routes\";\nimport supplierRoutes      from \"./routes/supplier.routes\";\nimport refundRoutes        from \"./routes/refund.routes\";\nimport giftCardRoutes      from \"./routes/giftCard.routes\";\nimport customerAccountRoutes from \"./routes/customerAccount.routes\";\nimport funnelRoutes        from \"./routes/funnel.routes\";\nimport apiKeyRoutes        from \"./routes/apiKey.routes\";\nimport webhookRoutes       from \"./routes/webhook.routes\";\nimport returnsRoutes       from \"./routes/returns.routes\";\nimport twoFARoutes         from \"./routes/twoFA.routes\";\nimport productSubscriptionRoutes from \"./routes/productSubscription.routes\";\nimport onboardingRoutes  from \"./routes/onboarding.routes\";\nimport milestoneRoutes   from \"./routes/milestone.routes\";\nimport contactRoutes     from \"./routes/contact.routes\";\nimport bundleRoutes      from \"./routes/bundle.routes\";\nimport groupBuyRoutes    from \"./routes/groupbuy.routes\";\nimport referralRoutes    from \"./routes/referral.routes\";\nimport navLevelRoutes    from \"./routes/navlevel.routes\";\nimport reportsRoutes     from \"./routes/reports.routes\";\nimport billingRoutes from \"./routes/billing.routes\";\nimport waitlistRoutes      from \"./routes/waitlist.routes\";\n\n// KAI CORE\nimport kaiRoutes from \"./routes/kai.routes\";\n\n// KAI EXPANSIONS\nimport kaiPowerRoutes from \"./routes/kai.power.routes\";\nimport featuresRoutes from \"./routes/features.routes\";\nimport loyaltyRoutes from \"./routes/loyalty.routes\";\nimport superchargeRoutes from \"./routes/supercharge.routes\";\nimport kaiAgentRoutes from \"./routes/kai.agent.routes\";\nimport themeRoutes from \"./routes/theme.routes\";\n\n// Controllers (Advanced AI + Automation)\nimport productIntelRoutes from \"./controllers/product.intel.controller\";\nimport intelRoutes from \"./controllers/kai.intelligence.controller\";\nimport fulfillmentRoutes from \"./controllers/fulfillment.controller\";\n\nconst app = express();\n\n// TRUST PROXY\nif (process.env.NODE_ENV === \"production\") {\n  app.set(\"trust proxy\", 1);\n}\n\n// SECURITY\napp.use(helmet({\n  crossOriginResourcePolicy: { policy: \"cross-origin\" },\n  contentSecurityPolicy: {\n    directives: {\n      defaultSrc: [\"'self'\"],\n      scriptSrc: [\"'self'\", \"https://js.stripe.com\"],\n      frameSrc: [\"'self'\", \"https://js.stripe.com\"],\n      connectSrc: [\"'self'\", \"https://api.stripe.com\"],\n      imgSrc: [\"'self'\", \"data:\", \"https:\"],\n      styleSrc: [\"'self'\", \"'unsafe-inline'\"],\n    },\n  },\n}));\n\n// CORS\nconst allowedOrigins = [\n  process.env.FRONTEND_URL || \"http://localhost:3000\",\n  \"http://localhost:3000\",\n  \"https://dropos-frontend1.vercel.app\",\n  \"https://droposhq.com\",\n  \"https://www.droposhq.com\",\n].filter(Boolean);\n\napp.use(cors({\n  origin: (origin, callback) => {\n    if (!origin || allowedOrigins.includes(origin) || origin.endsWith(\".vercel.app\")) {\n      callback(null, true);\n    } else {\n      callback(null, true);\n    }\n  },\n  credentials: true,\n}));\n\n// WEBHOOK RAW BODY\napp.use(\"/api/payments/webhook/stripe\", express.raw({ type: \"application/json\" }));\napp.use(\"/api/payments/webhook/paystack\", express.raw({ type: \"application/json\" }));\napp.use(\"/api/payments/webhook/flutterwave\", express.raw({ type: \"application/json\" }));\n\n// BODY PARSER\napp.use(express.json({ limit: \"50mb\" }));\napp.use(express.urlencoded({ extended: true, limit: \"50mb\" }));\napp.use(cookieParser());\napp.use(compression());\n\n// QUERY SANITIZATION\napp.use((req, _res, next) => {\n  for (const key in req.query) {\n    if (Array.isArray(req.query[key])) {\n      req.query[key] = (req.query[key] as string[]).at(-1) as any;\n    }\n  }\n  next();\n});\n\n// STATIC\napp.use(\"/uploads\", express.static(path.join(process.cwd(), \"uploads\")));\n\n// LOGGING\nif (process.env.NODE_ENV !== \"test\") {\n  app.use(morgan(\"combined\"));\n  app.use(requestLogger);\n}\n\n// RATE LIMIT\napp.use(\"/api\", globalRateLimiter);\n\n// HEALTH\napp.get(\"/api/health\", (_req: Request, res: Response) => {\n  res.json({ status: \"ok\", service: \"DropOS API\" });\n});\n\n// CORE BUSINESS ROUTES\napp.use(\"/api/auth\",                 authRoutes);\napp.use(\"/api/stores\",               storeRoutes);\napp.use(\"/api/products\",             productRoutes);\napp.use(\"/api/orders\",               orderRoutes);\napp.use(\"/api/payments\",             paymentRoutes);\napp.use(\"/api/customers\",            customerRoutes);\napp.use(\"/api/admin\",                adminRoutes);\napp.use(\"/api/analytics\",            analyticsRoutes);\napp.use(\"/api/upload\",               uploadRoutes);\napp.use(\"/api/support\",              supportRoutes);\napp.use(\"/api/notifications\",        notificationRoutes);\napp.use(\"/api/coupons\",              couponRoutes);\napp.use(\"/api/discounts\",            discountRoutes);\napp.use(\"/api/affiliates\",           affiliateRoutes);\napp.use(\"/api/ai\",                   aiRoutes);\napp.use(\"/api/push\",                 pushRoutes);\napp.use(\"/api/shipping\",             shippingRoutes);\napp.use(\"/api/reviews\",              reviewRoutes);\napp.use(\"/api/invoices\",             invoiceRoutes);\napp.use(\"/api/email\",                emailRoutes);\napp.use(\"/api/emails\",               emailRoutes); // alias for frontend\napp.use(\"/api/abandoned-carts\",      abandonedCartRoutes);\napp.use(\"/api/notification-settings\",notifSettingsRoutes);\napp.use(\"/api/currency\",             currencyRoutes);\napp.use(\"/api/suppliers\",            supplierRoutes);\napp.use(\"/api/refunds\",              refundRoutes);\napp.use(\"/api/gift-cards\",           giftCardRoutes);\napp.use(\"/api/customer-auth\",        customerAccountRoutes);\napp.use(\"/api/funnel\",               funnelRoutes);\napp.use(\"/api/api-keys\",             apiKeyRoutes);\napp.use(\"/api/webhooks\",             webhookRoutes);\napp.use(\"/api/ops\",                  returnsRoutes);\napp.use(\"/api/returns\",              returnsRoutes); // alias for frontend\napp.use(\"/api/2fa\",                  twoFARoutes);\napp.use(\"/api/product-subscriptions\",productSubscriptionRoutes);\napp.use(\"/api/upsell\",               upsellRoutes);\napp.use(\"/api/waitlist\",             waitlistRoutes);\n\n// KAI SYSTEM\n// SSE streaming needs special CORS handling\napp.options(\"/api/kai/smart-chat\", (req: any, res: any) => {\n  res.setHeader(\"Access-Control-Allow-Origin\", req.headers.origin || \"*\");\n  res.setHeader(\"Access-Control-Allow-Methods\", \"POST, OPTIONS\");\n  res.setHeader(\"Access-Control-Allow-Headers\", \"Content-Type, Authorization, Accept\");\n  res.status(204).send();\n});\napp.use(\"/api/kai\",              kaiRoutes);\napp.use(\"/api/billing\",          billingRoutes);\napp.use(\"/api/fulfillment\",       fulfillmentRoutes);\napp.use(\"/api/referral\",          referralRoutes);\napp.use(\"/api/intel\",             intelRoutes);\n\napp.use(\"/api/kai/power\",        kaiPowerRoutes);\napp.use(\"/api/kai/agent\",        kaiAgentRoutes);\napp.use(\"/api/features\",         featuresRoutes);\napp.use(\"/api/loyalty\",          loyaltyRoutes);\napp.use(\"/api/super\",            superchargeRoutes);\napp.use(\"/api/broadcasts\",       superchargeRoutes); // alias for frontend\napp.use(\"/api/theme\",            themeRoutes);\napp.use(\"/api/products/intel\",   productIntelRoutes);\napp.use(\"/api/intel\",            intelRoutes);\napp.use(\"/api/fulfillment\",      fulfillmentRoutes);\n\n// ERRORS\napp.use(\"/api/onboarding\",    onboardingRoutes);\napp.use(\"/api/milestones\",     milestoneRoutes);\napp.use(\"/api/contact\",        contactRoutes);\napp.use(\"/api/bundles\",        bundleRoutes);\napp.use(\"/api/group-buy\",      groupBuyRoutes);\napp.use(\"/api/nav-level\",      navLevelRoutes);\napp.use(\"/api/reports\",        reportsRoutes);\napp.use(\"/api/virtual-account\", virtualAccountRoutes);\napp.use(\"/api/whatsapp\",       whatsappRoutes);\napp.use(\"/api/delivery\",       deliveryRoutes);\napp.use(notFound);\napp.use(errorHandler);\n\nexport default app;","frontend/src/components/dashboard/PaymentsSection.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { useQuery, useMutation } from \"@tanstack/react-query\";\nimport { api } from \"../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport { CheckCircle, AlertCircle, RefreshCw, Building2, ChevronDown } from \"lucide-react\";\n\ninterface PaymentsSectionProps {\n  t: any;\n  storeId?: string;\n}\n\nexport function PaymentsSection({ t, storeId }: PaymentsSectionProps) {\n  const [bankCode,       setBankCode]       = useState(\"\");\n  const [bankName,       setBankName]       = useState(\"\");\n  const [accountNumber,  setAccountNumber]  = useState(\"\");\n  const [verifiedName,   setVerifiedName]   = useState(\"\");\n  const [isVerifying,    setIsVerifying]    = useState(false);\n  const [verifyError,    setVerifyError]    = useState(\"\");\n  const [whatsapp,       setWhatsapp]       = useState(\"\");\n  const [whatsappSaved,  setWhatsappSaved]  = useState(false);\n\n  const inp = {\n    width:\"100%\", padding:\"11px 14px\", borderRadius:11,\n    border:`1px solid ${t.border}`,\n    background:\"rgba(255,255,255,0.05)\",\n    color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\",\n  };\n\n  // Load banks\n  const { data: banks = [] } = useQuery<any[]>({\n    queryKey: [\"ng-banks\"],\n    queryFn: () => api.get(\"/banks\").then(r => r.data.data),\n    staleTime: Infinity,\n  });\n\n  // Load current bank info\n  const { data: bankInfo } = useQuery<any>({\n    queryKey: [\"bank-info\", storeId],\n    queryFn: () => api.get(`/banks/${storeId}`).then(r => r.data.data),\n    enabled: !!storeId,\n  });\n\n  // Verify account name automatically when 10 digits entered\n  useEffect(() => {\n    if (accountNumber.length === 10 && bankCode) {\n      setVerifyError(\"\");\n      setVerifiedName(\"\");\n      setIsVerifying(true);\n      api.post(\"/banks/verify\", { accountNumber, bankCode })\n        .then(r => { setVerifiedName(r.data.data.accountName); })\n        .catch(e => { setVerifyError(e.response?.data?.error || \"Could not verify account\"); })\n        .finally(() => setIsVerifying(false));\n    } else {\n      setVerifiedName(\"\");\n      setVerifyError(\"\");\n    }\n  }, [accountNumber, bankCode]);\n\n  const connectMut = useMutation({\n    mutationFn: () => api.post(`/banks/${storeId}/connect`, {\n      bankCode, bankName, accountNumber, accountName: verifiedName,\n    }),\n    onSuccess: (r) => {\n      toast.success(r.data.message || \"Bank account connected!\");\n    },\n    onError: (e: any) => toast.error(e.response?.data?.error || \"Connection failed\"),\n  });\n\n  const saveWhatsappMut = useMutation({\n    mutationFn: () => api.put(`/stores/${storeId}`, { whatsappPhone: whatsapp }),\n    onSuccess: () => { setWhatsappSaved(true); setTimeout(() => setWhatsappSaved(false), 3000); },\n    onError: () => toast.error(\"Save failed\"),\n  });\n\n  const isConnected = bankInfo?.paystackConnected;\n\n  return (\n    <div style={{ display:\"flex\", flexDirection:\"column\", gap:20 }}>\n      <div>\n        <h2 style={{ fontSize:14, fontWeight:800, color:t.text, margin:\"0 0 4px\", letterSpacing:\"-0.02em\" }}>\n          Payment Settings\n        </h2>\n        <p style={{ fontSize:12, color:t.muted, margin:0 }}>\n          Connect your bank account to receive 98% of every sale directly. DropOS keeps 2% as platform fee.\n        </p>\n      </div>\n\n      {/* How it works — simple visual */}\n      <div style={{ padding:16, borderRadius:14, background:\"rgba(16,185,129,0.04)\", border:\"1px solid rgba(16,185,129,0.12)\" }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:0, justifyContent:\"center\", flexWrap:\"wrap\", gap:8 }}>\n          {[\n            { label:\"Customer pays\", sub:\"e.g. ₦10,000\", color:\"rgba(255,255,255,0.7)\", bg:\"rgba(255,255,255,0.06)\" },\n            { label:\"→\", sub:\"\", color:\"rgba(255,255,255,0.3)\", bg:\"transparent\" },\n            { label:\"You get\", sub:\"₦9,800 (98%)\", color:\"#10B981\", bg:\"rgba(16,185,129,0.1)\" },\n            { label:\"+\", sub:\"\", color:\"rgba(255,255,255,0.3)\", bg:\"transparent\" },\n            { label:\"DropOS fee\", sub:\"₦200 (2%)\", color:\"#8B5CF6\", bg:\"rgba(107,53,232,0.1)\" },\n          ].map((item, i) => item.label === \"→\" || item.label === \"+\" ? (\n            <span key={i} style={{ fontSize:16, color:item.color, fontWeight:700 }}>{item.label}</span>\n          ) : (\n            <div key={i} style={{ padding:\"8px 14px\", borderRadius:10, background:item.bg, textAlign:\"center\" }}>\n              <p style={{ fontSize:12, fontWeight:700, color:item.color, margin:0 }}>{item.label}</p>\n              {item.sub && <p style={{ fontSize:11, color:item.color, margin:0, opacity:0.8 }}>{item.sub}</p>}\n            </div>\n          ))}\n        </div>\n        <p style={{ fontSize:11, color:\"rgba(16,185,129,0.7)\", textAlign:\"center\", margin:\"10px 0 0\", fontWeight:600 }}>\n          Money goes directly to your bank account. No Paystack account needed.\n        </p>\n      </div>\n\n      {/* Current status */}\n      {isConnected && bankInfo && (\n        <div style={{ padding:14, borderRadius:12, background:\"rgba(16,185,129,0.05)\", border:\"1px solid rgba(16,185,129,0.15)\", display:\"flex\", alignItems:\"center\", gap:12 }}>\n          <CheckCircle size={18} color=\"#10B981\"/>\n          <div>\n            <p style={{ fontSize:13, fontWeight:700, color:\"#10B981\", margin:0 }}>Bank account connected</p>\n            <p style={{ fontSize:12, color:t.muted, margin:\"2px 0 0\" }}>\n              {bankInfo.accountName} · {bankInfo.bankName} · {bankInfo.accountNumber}\n            </p>\n          </div>\n          <button\n            onClick={() => { setBankCode(\"\"); setAccountNumber(\"\"); setVerifiedName(\"\"); }}\n            style={{ marginLeft:\"auto\", fontSize:11, color:t.muted, background:\"none\", border:`1px solid ${t.border}`, borderRadius:8, padding:\"4px 10px\", cursor:\"pointer\", fontFamily:\"inherit\" }}>\n            Update\n          </button>\n        </div>\n      )}\n\n      {/* Bank account form */}\n      {!isConnected && (\n        <div style={{ background:t.card, borderRadius:16, padding:20, border:`1px solid ${t.border}` }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:18 }}>\n            <Building2 size={16} color=\"#8B5CF6\"/>\n            <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:0 }}>Connect your bank account</p>\n          </div>\n\n          {/* Bank selector */}\n          <div style={{ marginBottom:12 }}>\n            <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Your bank</label>\n            <div style={{ position:\"relative\" }}>\n              <select value={bankCode}\n                onChange={e => {\n                  setBankCode(e.target.value);\n                  setBankName(e.target.options[e.target.selectedIndex].text);\n                }}\n                style={{ ...inp, appearance:\"none\", paddingRight:36 }}>\n                <option value=\"\">Select your bank</option>\n                {banks.map((b: any) => (\n                  <option key={b.code} value={b.code}>{b.name}</option>\n                ))}\n              </select>\n              <ChevronDown size={14} style={{ position:\"absolute\", right:12, top:\"50%\", transform:\"translateY(-50%)\", color:t.muted, pointerEvents:\"none\" }}/>\n            </div>\n          </div>\n\n          {/* Account number */}\n          <div style={{ marginBottom:8 }}>\n            <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Account number</label>\n            <input\n              value={accountNumber}\n              onChange={e => setAccountNumber(e.target.value.replace(/\\D/g, \"\").slice(0, 10))}\n              placeholder=\"10-digit NUBAN\"\n              maxLength={10}\n              style={inp}\n            />\n          </div>\n\n          {/* Verification status */}\n          {isVerifying && (\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"8px 12px\", borderRadius:9, background:\"rgba(107,53,232,0.06)\", marginBottom:8 }}>\n              <RefreshCw size={12} color=\"#8B5CF6\" style={{ animation:\"spin 0.7s linear infinite\" }}/>\n              <span style={{ fontSize:12, color:\"#8B5CF6\" }}>Verifying account…</span>\n            </div>\n          )}\n          {verifiedName && !isVerifying && (\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"10px 14px\", borderRadius:10, background:\"rgba(16,185,129,0.08)\", border:\"1px solid rgba(16,185,129,0.2)\", marginBottom:8 }}>\n              <CheckCircle size={14} color=\"#10B981\"/>\n              <div>\n                <p style={{ fontSize:12, color:t.muted, margin:0 }}>Account name</p>\n                <p style={{ fontSize:14, fontWeight:800, color:\"#10B981\", margin:0, letterSpacing:\"-0.01em\" }}>{verifiedName}</p>\n              </div>\n            </div>\n          )}\n          {verifyError && !isVerifying && (\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"8px 12px\", borderRadius:9, background:\"rgba(239,68,68,0.06)\", border:\"1px solid rgba(239,68,68,0.15)\", marginBottom:8 }}>\n              <AlertCircle size={12} color=\"#EF4444\"/>\n              <span style={{ fontSize:12, color:\"#EF4444\" }}>{verifyError}</span>\n            </div>\n          )}\n\n          <button\n            onClick={() => connectMut.mutate()}\n            disabled={!verifiedName || !bankCode || connectMut.isPending}\n            style={{ width:\"100%\", padding:\"12px 0\", marginTop:8, borderRadius:12, border:\"none\", cursor:\"pointer\", background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\", fontSize:14, fontWeight:700, fontFamily:\"inherit\", opacity:(!verifiedName||!bankCode)?0.4:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:8, boxShadow:\"0 4px 16px rgba(107,53,232,0.25)\" }}>\n            {connectMut.isPending\n              ? <><RefreshCw size={14} style={{ animation:\"spin 0.7s linear infinite\" }}/> Connecting…</>\n              : \"Connect bank account\"}\n          </button>\n        </div>\n      )}\n\n      {/* WhatsApp chat bubble */}\n      <div style={{ background:t.card, borderRadius:16, padding:20, border:`1px solid ${t.border}` }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:14 }}>\n          <div style={{ width:30, height:30, borderRadius:8, background:\"rgba(37,211,102,0.1)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n            <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"#25D366\"><path d=\"M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z\"/></svg>\n          </div>\n          <div>\n            <p style={{ fontSize:13, fontWeight:700, color:t.text, margin:0 }}>WhatsApp Chat Button</p>\n            <p style={{ fontSize:11, color:t.muted, margin:0 }}>Customers can message you directly from your store</p>\n          </div>\n        </div>\n        <input value={whatsapp} onChange={e => setWhatsapp(e.target.value)}\n          placeholder=\"+2348012345678\" style={inp}/>\n        <p style={{ fontSize:11, color:t.muted, margin:\"6px 0 12px\" }}>Include country code (+234 for Nigeria)</p>\n        <button onClick={() => saveWhatsappMut.mutate()}\n          style={{ padding:\"9px 18px\", borderRadius:10, border:\"none\", cursor:\"pointer\", background:\"rgba(37,211,102,0.15)\", color:\"#25D366\", fontSize:13, fontWeight:700, fontFamily:\"inherit\" }}>\n          {whatsappSaved ? \"✓ Saved\" : \"Save\"}\n        </button>\n      </div>\n\n      <style>{\"@keyframes spin{to{transform:rotate(360deg)}}\"}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/settings/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme, useToast, useConfirm } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport { User, Bell, Shield, Palette, Globe, Trash2, Eye, EyeOff, ChevronRight, Camera, Sun, Moon, Check, CreditCard } from \"lucide-react\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\" };\nconst T = {\n  dark:  { card: \"#181230\", border: \"rgba(255,255,255,0.06)\", text: \"#fff\", muted: \"rgba(255,255,255,0.38)\", faint: \"rgba(255,255,255,0.04)\", input: \"rgba(255,255,255,0.05)\" },\n  light: { card: \"#fff\",    border: \"rgba(15,5,32,0.07)\",    text: \"#0D0918\", muted: \"rgba(13,9,24,0.45)\", faint: \"rgba(15,5,32,0.03)\", input: \"rgba(15,5,32,0.04)\" },\n};\n\nconst SECTIONS = [\n  { id: \"profile\",       label: \"Profile\",      icon: User    },\n  { id: \"notifications\", label: \"Alerts\",       icon: Bell    },\n  { id: \"security\",      label: \"Security\",     icon: Shield  },\n  { id: \"appearance\",    label: \"Appearance\",   icon: Palette },\n  { id: \"domain\",        label: \"Domain\",        icon: Globe   },\n  { id: \"payments\",      label: \"Payments\",     icon: CreditCard },\n  { id: \"danger\",        label: \"Danger Zone\",  icon: Trash2  },\n];\n\nfunction SettingRow({ label, desc, children, t }: any) {\n  return (\n    <div className=\"flex items-center justify-between py-4 gap-4\" style={{ borderBottom: `1px solid ${t.border}` }}>\n      <div className=\"flex-1 min-w-0\">\n        <p className=\"text-sm font-semibold\" style={{ color: t.text }}>{label}</p>\n        {desc && <p className=\"text-xs mt-0.5\" style={{ color: t.muted }}>{desc}</p>}\n      </div>\n      <div className=\"flex-shrink-0\">{children}</div>\n    </div>\n  );\n}\n\nfunction Toggle({ value, onChange }: { value: boolean; onChange: (v: boolean) => void }) {\n  return (\n    <button onClick={() => onChange(!value)}\n      className=\"relative flex-shrink-0 transition-all\"\n      style={{ width: 44, height: 24, borderRadius: 12, border: \"none\", cursor: \"pointer\", background: value ? V.v500 : \"rgba(128,128,128,0.2)\" }}>\n      <div className=\"absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all shadow-sm\" style={{ left: value ? 22 : 2 }} />\n    </button>\n  );\n}\n\nfunction TextInput({ label, value, onChange, type = \"text\", placeholder, t, disabled }: any) {\n  const [show, setShow] = useState(false);\n  return (\n    <div>\n      <label className=\"block text-xs font-semibold mb-1.5\" style={{ color: t.muted }}>{label}</label>\n      <div className=\"relative\">\n        <input\n          type={type === \"password\" ? (show ? \"text\" : \"password\") : type}\n          value={value} onChange={e => onChange(e.target.value)}\n          placeholder={placeholder} disabled={disabled}\n          className=\"w-full px-4 py-3 rounded-xl text-sm outline-none\"\n          style={{ border: `1px solid ${t.border}`, background: disabled ? t.faint : t.input, color: t.text, fontFamily: \"inherit\", paddingRight: type === \"password\" ? 44 : 16, opacity: disabled ? 0.6 : 1 }}\n        />\n        {type === \"password\" && (\n          <button type=\"button\" onClick={() => setShow(!show)} className=\"absolute right-3 top-1/2 -translate-y-1/2\" style={{ border: \"none\", background: \"none\", cursor: \"pointer\", color: t.muted }}>\n            {show ? <EyeOff size={14} /> : <Eye size={14} />}\n          </button>\n        )}\n      </div>\n    </div>\n  );\n}\n\n\nfunction DomainSection({ t, storeId }: { t: any; storeId?: string }) {\n  const [domain, setDomain] = useState(\"\");\n  const [saving, setSaving] = useState(false);\n  const [verified, setVerified] = useState(false);\n\n  const save = async () => {\n    if (!domain.trim()) return;\n    setSaving(true);\n    try {\n      const { api } = await import(\"../../../lib/api\");\n      await api.put(`/stores/${storeId}/custom-domain`, { domain: domain.trim().toLowerCase() });\n      setVerified(true);\n      toast.success(\"Domain saved! Now add the CNAME record below to your DNS.\");\n    } catch {\n      toast.error(\"Backend offline — save your domain when Render is live\");\n    } finally { setSaving(false); }\n  };\n\n  return (\n    <div className=\"space-y-4\">\n      <div>\n        <label className=\"block text-xs font-semibold mb-2\" style={{ color: t.muted }}>Custom domain</label>\n        <div className=\"flex gap-2\">\n          <input value={domain} onChange={e => setDomain(e.target.value)} placeholder=\"store.yourbrand.com\"\n            className=\"flex-1 px-4 py-2.5 rounded-xl text-sm outline-none\"\n            style={{ background: t.faint, border: `1px solid ${t.border}`, color: t.text, fontFamily: \"inherit\" }}/>\n          <button onClick={save} disabled={!domain.trim() || saving}\n            className=\"px-4 py-2.5 rounded-xl text-sm font-bold text-white disabled:opacity-50\"\n            style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\", border: \"none\", cursor: \"pointer\" }}>\n            {saving ? \"Saving...\" : \"Save\"}\n          </button>\n        </div>\n        <p className=\"text-xs mt-1.5\" style={{ color: t.muted }}>Must be a subdomain you control (e.g. shop.yourbrand.com)</p>\n      </div>\n      {(verified || domain) && (\n        <div className=\"p-4 rounded-xl space-y-2\" style={{ background: \"rgba(107,53,232,0.06)\", border: \"1px solid rgba(107,53,232,0.2)\" }}>\n          <p className=\"text-xs font-bold\" style={{ color: \"#A78BFA\" }}>Add this CNAME record to your DNS:</p>\n          <div className=\"grid grid-cols-2 gap-2 text-xs\">\n            <div><p style={{ color: t.muted, marginBottom: 2 }}>Type</p><p className=\"font-mono font-bold\" style={{ color: t.text }}>CNAME</p></div>\n            <div><p style={{ color: t.muted, marginBottom: 2 }}>Name</p><p className=\"font-mono font-bold\" style={{ color: t.text }}>{domain.split(\".\")[0] || \"store\"}</p></div>\n            <div className=\"col-span-2\"><p style={{ color: t.muted, marginBottom: 2 }}>Value</p><p className=\"font-mono font-bold text-xs\" style={{ color: t.text }}>cname.dropos-dns.com</p></div>\n          </div>\n          <p className=\"text-xs\" style={{ color: t.muted }}>DNS changes take 10-60 minutes to propagate. SSL is automatic.</p>\n        </div>\n      )}\n    </div>\n  );\n}\n\nfunction PaymentsSection({ t, storeId, store }: { t: any; storeId?: string; store?: any }) {\n  const [pk, setPk]   = useState(store?.paystackPublicKey || \"\");\n  const [sk, setSk]   = useState(\"\");\n  const [wa, setWa]   = useState(store?.whatsappPhone || \"\");\n  const [saved, setSaved] = useState(false);\n  const { api } = require(\"../../../lib/api\");\n\n  const saveMut = { \n    mutate: async () => {\n      try {\n        const { default: apiMod } = await import(\"../../../lib/api\");\n        await apiMod.api.put(`/stores/${storeId}`, {\n          paystackPublicKey: pk || undefined,\n          paystackSecretKey: sk || undefined,\n          whatsappPhone: wa || undefined,\n        });\n        setSaved(true);\n        setTimeout(() => setSaved(false), 3000);\n      } catch {}\n    },\n    isPending: false,\n  };\n\n  const inp = {\n    width:\"100%\", padding:\"10px 14px\", borderRadius:10,\n    border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\",\n    color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\",\n  };\n\n  return (\n    <div style={{ display:\"flex\", flexDirection:\"column\", gap:20 }}>\n      <h2 className=\"text-sm font-bold\" style={{ color:t.text }}>Payment Settings</h2>\n\n      {/* Paystack */}\n      <div style={{ padding:18, borderRadius:14, background:t.faint, border:`1px solid ${t.border}` }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:14 }}>\n          <div style={{ width:32, height:32, borderRadius:9, background:\"rgba(245,158,11,0.1)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:16 }}>₦</div>\n          <div>\n            <p className=\"text-sm font-bold\" style={{ color:t.text }}>Paystack</p>\n            <p className=\"text-xs\" style={{ color:t.muted }}>Accept Naira payments — card, bank transfer, USSD</p>\n          </div>\n        </div>\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:10 }}>\n          <div>\n            <label className=\"text-xs font-semibold block mb-1.5\" style={{ color:t.muted }}>Public Key</label>\n            <input value={pk} onChange={e => setPk(e.target.value)} type=\"text\" placeholder=\"pk_live_...\" style={inp}/>\n          </div>\n          <div>\n            <label className=\"text-xs font-semibold block mb-1.5\" style={{ color:t.muted }}>\n              Secret Key {store?.paystackPublicKey && <span style={{ color:\"#10B981\" }}>✓ Connected</span>}\n            </label>\n            <input value={sk} onChange={e => setSk(e.target.value)} type=\"password\" placeholder={store?.paystackPublicKey ? \"sk_live_•••••• (enter to update)\" : \"sk_live_...\"} style={inp}/>\n          </div>\n          <p className=\"text-xs\" style={{ color:t.muted }}>\n            Get keys from{\" \"}\n            <a href=\"https://dashboard.paystack.com/#/settings/developer\" target=\"_blank\" rel=\"noreferrer\" style={{ color:\"#6B35E8\" }}>\n              Paystack → Settings → API Keys\n            </a>\n          </p>\n        </div>\n      </div>\n\n      {/* WhatsApp */}\n      <div style={{ padding:18, borderRadius:14, background:t.faint, border:`1px solid ${t.border}` }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:12 }}>\n          <div style={{ width:32, height:32, borderRadius:9, background:\"rgba(37,211,102,0.1)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"#25D366\"><path d=\"M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z\"/></svg>\n          </div>\n          <div>\n            <p className=\"text-sm font-bold\" style={{ color:t.text }}>WhatsApp Chat Button</p>\n            <p className=\"text-xs\" style={{ color:t.muted }}>Shows a chat button on your storefront</p>\n          </div>\n        </div>\n        <label className=\"text-xs font-semibold block mb-1.5\" style={{ color:t.muted }}>Your WhatsApp number</label>\n        <input value={wa} onChange={e => setWa(e.target.value)} type=\"tel\" placeholder=\"+2348012345678\" style={inp}/>\n        <p className=\"text-xs mt-1.5\" style={{ color:t.muted }}>Include country code (+234 for Nigeria)</p>\n      </div>\n\n      <button\n        onClick={() => saveMut.mutate()}\n        style={{ display:\"inline-flex\", alignItems:\"center\", gap:6, padding:\"11px 24px\", borderRadius:12, border:\"none\", cursor:\"pointer\", background:\"linear-gradient(135deg,#6B35E8,#3D1C8A)\", color:\"#fff\", fontSize:13, fontWeight:700, fontFamily:\"inherit\", alignSelf:\"flex-start\" }}>\n        {saved ? \"✓ Saved!\" : \"Save payment settings\"}\n      </button>\n    </div>\n  );\n}\n\n\nexport default function SettingsPage() {\n  const { theme, toggle: toggleTheme } = useTheme();\n  const { show } = useToast();\n  const { confirm } = useConfirm();\n  const { user } = useAuthStore();\n  const isDark = theme === \"dark\";\n  const t = isDark ? T.dark : T.light;\n\n  const [activeSection, setActiveSection] = useState(\"profile\");\n  const [saving, setSaving] = useState(false);\n  const [name, setName]   = useState(user?.name || \"\");\n  const [email, setEmail] = useState(user?.email || \"\");\n  const [currentPw, setCurrentPw] = useState(\"\");\n  const [newPw, setNewPw]         = useState(\"\");\n  const [notifs, setNotifs] = useState({ orders: true, marketing: false, security: true, updates: true, kiro: true });\n\n  const handleSaveProfile = async () => {\n    setSaving(true);\n    try { await api.put(\"/auth/profile\", { name, email }); show(\"Profile saved\", \"success\"); }\n    catch { show(\"Saved locally (backend offline)\", \"info\"); }\n    finally { setSaving(false); }\n  };\n\n  const handleChangePassword = async () => {\n    if (!currentPw || !newPw) { show(\"Fill in both fields\", \"error\"); return; }\n    try { await api.put(\"/auth/password\", { currentPassword: currentPw, newPassword: newPw }); show(\"Password updated\", \"success\"); setCurrentPw(\"\"); setNewPw(\"\"); }\n    catch (e: any) { show(e.response?.data?.message || \"Failed\", \"error\"); }\n  };\n\n  const handleDelete = async () => {\n    const ok = await confirm({ title: \"Delete your account?\", message: \"This permanently deletes your account and all store data. Cannot be undone.\", confirmText: \"Yes, delete everything\", cancelText: \"Keep my account\", variant: \"danger\" });\n    if (ok) show(\"Account deletion requested\", \"info\");\n  };\n\n  return (\n    <div className=\"max-w-4xl mx-auto\">\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} className=\"mb-6\">\n        <h1 className=\"text-xl sm:text-2xl font-black tracking-tight\" style={{ color: t.text }}>Settings</h1>\n        <p className=\"text-xs sm:text-sm mt-1\" style={{ color: t.muted }}>Manage your account and preferences</p>\n      </motion.div>\n\n      <div className=\"flex flex-col sm:flex-row gap-4\">\n        {/* Section sidebar - horizontal scroll on mobile, vertical on desktop */}\n        <div className=\"sm:w-44 flex-shrink-0\">\n          <div className=\"flex sm:flex-col gap-1 overflow-x-auto pb-1 sm:pb-0\" style={{ scrollbarWidth: \"none\" }}>\n            {SECTIONS.map(s => {\n              const Icon = s.icon;\n              const active = activeSection === s.id;\n              return (\n                <button key={s.id} onClick={() => setActiveSection(s.id)}\n                  className=\"flex items-center gap-2.5 px-3 py-2.5 rounded-xl text-left transition-all whitespace-nowrap sm:whitespace-normal flex-shrink-0 sm:flex-shrink w-auto sm:w-full\"\n                  style={{ background: active ? \"rgba(107,53,232,0.1)\" : \"transparent\", border: `1px solid ${active ? \"rgba(107,53,232,0.25)\" : \"transparent\"}`, color: active ? V.v300 : t.muted }}>\n                  <Icon size={14} />\n                  <span className=\"text-xs font-semibold\">{s.label}</span>\n                </button>\n              );\n            })}\n          </div>\n        </div>\n\n        {/* Content */}\n        <div className=\"flex-1 min-w-0\">\n          <motion.div key={activeSection} initial={{ opacity: 0, x: 8 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.15 }}\n            className=\"rounded-2xl p-4 sm:p-6\" style={{ background: t.card, border: `1px solid ${t.border}` }}>\n\n            {activeSection === \"profile\" && (\n              <div className=\"space-y-4\">\n                <h2 className=\"text-sm font-bold mb-4\" style={{ color: t.text }}>Profile</h2>\n                {/* Avatar */}\n                <div className=\"flex items-center gap-4 mb-2\">\n                  <div className=\"relative\">\n                    <div className=\"w-16 h-16 rounded-2xl flex items-center justify-center text-2xl font-black text-white\" style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                      {name?.[0]?.toUpperCase() || \"U\"}\n                    </div>\n                    <button className=\"absolute -bottom-1 -right-1 w-6 h-6 rounded-full flex items-center justify-center text-white\" style={{ background: V.v500 }}>\n                      <Camera size={10} />\n                    </button>\n                  </div>\n                  <div>\n                    <p className=\"text-sm font-semibold\" style={{ color: t.text }}>{name || \"Your Name\"}</p>\n                    <p className=\"text-xs\" style={{ color: t.muted }}>{email}</p>\n                  </div>\n                </div>\n                <TextInput label=\"Full Name\" value={name} onChange={setName} placeholder=\"Your name\" t={t} />\n                <TextInput label=\"Email\" value={email} onChange={setEmail} type=\"email\" placeholder=\"you@example.com\" t={t} />\n                <button onClick={handleSaveProfile} disabled={saving}\n                  className=\"w-full sm:w-auto px-6 py-2.5 rounded-xl text-sm font-bold text-white flex items-center justify-center gap-2 disabled:opacity-60\"\n                  style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                  {saving ? \"Saving...\" : \"Save Profile\"}\n                </button>\n              </div>\n            )}\n\n            {activeSection === \"notifications\" && (\n              <div>\n                <h2 className=\"text-sm font-bold mb-1\" style={{ color: t.text }}>Notification Preferences</h2>\n                <p className=\"text-xs mb-4\" style={{ color: t.muted }}>Choose what you want to be notified about</p>\n                {[\n                  { key: \"orders\",    label: \"New Orders\",          desc: \"Get notified when a customer places an order\" },\n                  { key: \"kiro\",      label: \"KIRO Alerts\",         desc: \"Morning briefs, opportunities, and urgent alerts\" },\n                  { key: \"security\",  label: \"Security Alerts\",     desc: \"Login attempts and account security\" },\n                  { key: \"marketing\", label: \"Marketing Tips\",      desc: \"Product ideas and growth suggestions\" },\n                  { key: \"updates\",   label: \"Platform Updates\",    desc: \"New features and improvements\" },\n                ].map(n => (\n                  <SettingRow key={n.key} label={n.label} desc={n.desc} t={t}>\n                    <Toggle value={notifs[n.key as keyof typeof notifs]} onChange={v => setNotifs(p => ({ ...p, [n.key]: v }))} />\n                  </SettingRow>\n                ))}\n              </div>\n            )}\n\n            {activeSection === \"security\" && (\n              <div className=\"space-y-4\">\n                <h2 className=\"text-sm font-bold mb-4\" style={{ color: t.text }}>Security</h2>\n                <TextInput label=\"Current Password\" value={currentPw} onChange={setCurrentPw} type=\"password\" placeholder=\"••••••••\" t={t} />\n                <TextInput label=\"New Password\" value={newPw} onChange={setNewPw} type=\"password\" placeholder=\"Min 8 characters\" t={t} />\n                <button onClick={handleChangePassword}\n                  className=\"w-full sm:w-auto px-6 py-2.5 rounded-xl text-sm font-bold text-white\"\n                  style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                  Update Password\n                </button>\n                <div className=\"pt-4\" style={{ borderTop: `1px solid ${t.border}` }}>\n                  <SettingRow label=\"Two-Factor Authentication\" desc=\"Add an extra layer of security to your account\" t={t}>\n                    <button className=\"text-xs font-semibold px-3 py-1.5 rounded-lg\" style={{ border: `1px solid ${t.border}`, color: t.muted }}>Enable</button>\n                  </SettingRow>\n                </div>\n              </div>\n            )}\n\n            {activeSection === \"payments\" && (\n              <PaymentsSection t={t} storeId={user?.stores?.[0]?.id} store={user?.stores?.[0]} />\n            )}\n\n            {activeSection === \"appearance\" && (\n              <div>\n                <h2 className=\"text-sm font-bold mb-4\" style={{ color: t.text }}>Appearance</h2>\n                <SettingRow label=\"Theme\" desc=\"Choose how the dashboard looks\" t={t}>\n                  <div className=\"flex gap-2\">\n                    {[{ mode: \"dark\", icon: Moon, label: \"Dark\" }, { mode: \"light\", icon: Sun, label: \"Light\" }].map(opt => {\n                      const Icon = opt.icon;\n                      const active = theme === opt.mode;\n                      return (\n                        <button key={opt.mode} onClick={toggleTheme}\n                          className=\"flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-semibold transition-all\"\n                          style={{ background: active ? V.v500 : t.faint, color: active ? \"#fff\" : t.muted, border: `1px solid ${active ? V.v500 : t.border}` }}>\n                          <Icon size={12} /> {opt.label}\n                          {active && <Check size={11} />}\n                        </button>\n                      );\n                    })}\n                  </div>\n                </SettingRow>\n              </div>\n            )}\n\n      \n      {activeSection === \"domain\" && (\n        <div className=\"space-y-0\" style={{ borderRadius: 16, overflow: \"hidden\", border: `1px solid ${t.border}` }}>\n          <div className=\"p-5\" style={{ borderBottom: `1px solid ${t.border}` }}>\n            <h2 className=\"font-bold text-sm mb-1\" style={{ color: t.text }}>Custom Domain</h2>\n            <p className=\"text-xs\" style={{ color: t.muted }}>Connect your own domain instead of the dropos.io subdomain</p>\n          </div>\n          <div className=\"p-5 space-y-4\">\n            <div>\n              <label className=\"block text-xs font-semibold mb-2\" style={{ color: t.muted }}>Your subdomain (always free)</label>\n              <div className=\"flex items-center gap-2 px-4 py-2.5 rounded-xl\" style={{ background: t.faint, border: `1px solid ${t.border}` }}>\n                <span className=\"text-sm font-semibold\" style={{ color: t.text }}>{user?.stores?.[0]?.slug || \"yourstore\"}</span>\n                <span className=\"text-sm\" style={{ color: t.muted }}>.droposhq.com</span>\n              </div>\n            </div>\n            <DomainSection t={t} storeId={user?.stores?.[0]?.id} />\n          </div>\n        </div>\n      )}\n\n      {activeSection === \"danger\" && (\n              <div>\n                <h2 className=\"text-sm font-bold mb-1 text-red-400\">Danger Zone</h2>\n                <p className=\"text-xs mb-6\" style={{ color: t.muted }}>These actions cannot be undone. Be very careful.</p>\n                <div className=\"p-4 rounded-2xl\" style={{ border: \"1px solid rgba(239,68,68,0.25)\", background: \"rgba(239,68,68,0.05)\" }}>\n                  <p className=\"text-sm font-semibold text-red-400 mb-1\">Delete Account</p>\n                  <p className=\"text-xs mb-4\" style={{ color: t.muted }}>Permanently delete your account and all store data including products, orders, and customer information.</p>\n                  <button onClick={handleDelete} className=\"px-4 py-2 rounded-xl text-xs font-bold text-white\" style={{ background: \"#EF4444\" }}>\n                    Delete My Account\n                  </button>\n                </div>\n              </div>\n            )}\n\n          </motion.div>\n        </div>\n      </div>\n    </div>\n  );\n}\n","backend/prisma/schema.prisma":"// prisma/schema.prisma\n// DropOS - Full Multi-Tenant SaaS Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\n\nenum Role {\n  SUPER_ADMIN\n  STORE_OWNER\n  CUSTOMER\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n  BANNED\n}\n\nenum PlanType {\n  STARTER\n  PRO\n  ADVANCED\n}\n\nenum StoreStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING\n  ARCHIVED\n}\n\nenum ProductStatus {\n  ACTIVE\n  DRAFT\n  OUT_OF_STOCK\n  ARCHIVED\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  COMPLETED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n  DISPUTED\n}\n\nenum PaymentGateway {\n  STRIPE\n  PAYSTACK\n  FLUTTERWAVE\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n}\n\nenum SupportStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum LogLevel {\n  INFO\n  WARN\n  ERROR\n  CRITICAL\n}\n\n// ─── User ────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id                String     @id @default(uuid())\n  email             String     @unique\n  password          String\n  name              String\n  phone             String?\n  avatar            String?\n  role              Role       @default(STORE_OWNER)\n  status            UserStatus @default(PENDING_VERIFICATION)\n  emailVerified     Boolean    @default(false)\n  emailVerifyToken  String?\n  passwordResetToken String?\n  passwordResetExpiry DateTime?\n  twoFAEnabled      Boolean    @default(false)\n  twoFASecret       String?\n  lastLogin         DateTime?\n  loginAttempts     Int        @default(0)\n  lockedUntil       DateTime?\n  refreshToken      String?\n  adminNotes        String?\n  flags             String[]   @default([])\n  onboarded         Boolean    @default(false)\n  onboardNiche      String?\n  onboardStage      String?\n  onboardGoal       String?\n  onboardTemplate   String?\n  country           String?\n  city              String?\n  timezone          String?    @default(\"UTC\")\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  // Relations\n  stores            Store[]\n  kaiConversations  KaiConversation[]\n  subscription      Subscription?\n  supportTickets    SupportTicket[]\n  notifications     Notification[]\n  auditLogs         AuditLog[]\n  pushSubscriptions PushSubscription[]\n  referral          Referral?\n  refreshTokens     RefreshToken[]\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@map(\"users\")\n}\n\n// ─── Store ───────────────────────────────────────────────────────────────────\n\nmodel Store {\n  id              String      @id @default(uuid())\n  ownerId         String\n  name            String\n  slug            String      @unique\n  description     String?\n  logo            String?\n  banner          String?\n  domain          String?     @unique\n  customDomain    String?     @unique\n  templateId      String?\n  // Bank account — merchant receives 98% of sales directly to their bank\n  bankName            String?  // e.g. \"GTBank\"\n  bankCode            String?  // Paystack bank code e.g. \"058\"\n  accountNumber       String?  // 10-digit NUBAN\n  accountName         String?  // Verified account name\n  paystackSubCode     String?  // Paystack subaccount code — auto-created on bank setup\n  paystackConnected   Boolean  @default(false)\n  whatsappPhone       String?  // store-level WhatsApp for customer chat bubble\n  status          StoreStatus @default(ACTIVE)\n  primaryColor    String?     @default(\"#7c3aed\")\n  accentColor     String?     @default(\"#a855f7\")\n  theme           String?     @default(\"default\")\n  secondaryColor  String?\n  fontFamily      String?     @default(\"DM Sans\")\n  borderRadius    String?     @default(\"rounded\")\n  tagline         String?\n  announcement    String?\n  showReviews     Boolean     @default(true)\n  showInventory   Boolean     @default(true)\n  productsPerRow  Int         @default(4)\n  currency        String      @default(\"USD\")\n  country         String?\n  address         String?\n  supportEmail    String?\n  supportPhone    String?\n  taxRate         Float?      @default(0)\n  shippingEnabled Boolean     @default(true)\n  freeShippingMin Float?\n  metaTitle         String?\n  metaDescription   String?\n  // ── SMS / WhatsApp via Twilio ─────────────────────────────────────────────\n  suppliers           Supplier[]\n  fulfillmentOrders   FulfillmentOrder[]\n\n  // ── Multi-currency ───────────────────────────────────────────────────────────\n  supportedCurrencies Json?       // e.g. [\"USD\",\"EUR\",\"GBP\",\"NGN\"]\n  autoDetectCurrency  Boolean     @default(true)\n  smsEnabled        Boolean     @default(false)\n  smsPhone          String?     // owner's phone for incoming alerts  e.g. +2348012345678\n  whatsappEnabled   Boolean     @default(false)\n  whatsappPhone     String?     // owner's WhatsApp number\n  // ── Live Chat widget ────────────────────────────────────────────────────────\n  liveChatProvider  String?     // \"tawk\", \"crisp\", \"tidio\", \"whatsapp\", or null\n  liveChatId        String?     // Tawk.to property ID / Crisp website ID / Tidio key\n  liveChatEnabled   Boolean     @default(false)\n  // ── Social links ────────────────────────────────────────────────────────────\n  instagram         String?\n  tiktok            String?\n  facebook          String?\n  twitter           String?\n  notifyOwnerSms    Boolean     @default(true)   // SMS owner on new order\n  notifyCustomerSms Boolean     @default(false)\n  loyaltyEnabled    Boolean     @default(false)\n  themeSettings     Json?  // SMS customer on order + status\n  createdAt         DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  // Relations\n  owner           User        @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  products        Product[]\n  orders          Order[]\n  customers       StoreCustomer[]\n  payments        Payment[]\n  analytics       Analytics[]\n  shippingZones   ShippingZone[]\n  coupons         Coupon[]\n  reviews         Review[]\n  abandonedCarts  AbandonedCart[]\n\n  discounts       Discount[]\n  refunds         Refund[]\n  giftCards       GiftCard[]\n  webhooks        StoreWebhook[]\n  flashSales      FlashSale[]\n  backups         StoreBackup[]\n  apiKeys         ApiKey[]\n  returnRequests  ReturnRequest[]\n  affiliates      Affiliate[]\n  bundles              Bundle[]\n  groupBuys            GroupBuy[]\n  milestones           Milestone[]\n  whatsappBroadcasts   WhatsappBroadcast[]\n  @@index([ownerId])\n  @@index([slug])\n  @@index([status])\n  @@map(\"stores\")\n  integrations    StoreIntegration[]\n}\n\n// ─── Product ─────────────────────────────────────────────────────────────────\n\nmodel Product {\n  id              String        @id @default(uuid())\n  storeId         String\n  name            String\n  slug            String\n  description     String?\n  price           Float\n  comparePrice    Float?\n  costPrice       Float?\n  sku             String?\n  barcode         String?\n  weight          Float?\n  inventory       Int           @default(0)\n  trackInventory  Boolean       @default(true)\n  allowBackorder  Boolean       @default(false)\n  images          String[]      @default([])\n  category        String?\n  tags            String[]      @default([])\n  status          ProductStatus @default(DRAFT)\n  isDigital       Boolean       @default(false)\n  isActive        Boolean       @default(true)\n  sourceUrl       String?\n  stockQuantity   Int?\n  metadata        Json?\n  currency        String?\n  metaTitle       String?\n  metaDescription String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  // Relations\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  variants        ProductVariant[]\n  orderItems      OrderItem[]\n  reviews         Review[]\n  supplierProducts SupplierProduct[]\n  groupBuys       GroupBuy[]\n\n  @@unique([storeId, slug])\n  @@index([storeId])\n  @@index([status])\n  @@map(\"products\")\n}\n\nmodel ProductVariant {\n  id          String   @id @default(uuid())\n  productId   String\n  name        String\n  value       String\n  price       Float?\n  inventory   Int      @default(0)\n  sku         String?\n  image       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\n// ─── Store Customer ──────────────────────────────────────────────────────────\n\nmodel StoreCustomer {\n  id              String    @id @default(uuid())\n  storeId         String\n  email           String\n  name            String\n  phone           String?\n  address         Json?\n  emailVerified   Boolean   @default(false)\n  country         String?\n  totalSpent      Float     @default(0)\n  orderCount      Int       @default(0)\n  totalOrders     Int       @default(0)\n  city            String?\n  notes           String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  store           Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  orders          Order[]\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"store_customers\")\n}\n\n// ─── Order ───────────────────────────────────────────────────────────────────\n\nmodel Order {\n  id                String      @id @default(uuid())\n  orderNumber       String      @unique\n  storeId           String\n  customerId        String?\n  customerEmail     String\n  customerName      String\n  customerPhone     String?\n  shippingAddress   Json?\n  billingAddress    Json?\n  status            OrderStatus @default(PENDING)\n  subtotal          Float\n  shippingCost      Float       @default(0)\n  taxAmount         Float       @default(0)\n  discountAmount    Float       @default(0)\n  total             Float\n  currency          String      @default(\"USD\")\n  notes             String?\n  trackingNumber    String?\n  trackingUrl       String?\n  refundAmount      Float?\n  cancelReason      String?\n  fulfillmentStatus String      @default(\"UNFULFILLED\")\n  carrier         String?\n  shippedAt       DateTime?\n  paymentStatus   String      @default(\"PENDING\")\n  tax               Float       @default(0)\n  createdAt         DateTime    @default(now())\n  updatedAt         DateTime    @updatedAt\n\n  store             Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  customer          StoreCustomer? @relation(fields: [customerId], references: [id])\n  items             OrderItem[]\n  payment           Payment?\n  refunds           Refund[]\n  returns           ReturnRequest[]\n\n  @@index([storeId])\n  @@index([status])\n  @@index([orderNumber])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id          String   @id @default(uuid())\n  orderId     String\n  productId   String\n  variantId   String?\n  name        String\n  sku         String?\n  price       Float\n  quantity    Int\n  total       Float\n  image       String?\n  createdAt   DateTime @default(now())\n\n  order       Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product     Product  @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@map(\"order_items\")\n}\n\n// ─── Payment ─────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id                String         @id @default(uuid())\n  orderId           String         @unique\n  storeId           String\n  gateway           PaymentGateway\n  gatewayReference  String?\n  gatewayResponse   Json?\n  amount            Float\n  currency          String         @default(\"USD\")\n  platformFee       Float\n  platformFeePercent Float\n  storeEarnings     Float\n  status            PaymentStatus  @default(PENDING)\n  paidAt            DateTime?\n  refundedAt        DateTime?\n  metadata          Json?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  order             Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store             Store          @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([status])\n  @@index([gateway])\n  @@map(\"payments\")\n}\n\n// ─── Subscription ────────────────────────────────────────────────────────────\n\nmodel Subscription {\n  id                  String             @id @default(uuid())\n  userId              String             @unique\n  plan                PlanType           @default(STARTER)\n  status              SubscriptionStatus @default(ACTIVE)\n  currentPeriodStart  DateTime\n  currentPeriodEnd    DateTime\n  cancelAtPeriodEnd   Boolean            @default(false)\n  stripeSubId         String?\n  paystackSubCode     String?\n  price               Float\n  currency            String             @default(\"USD\")\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n\n  user                User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\n// ─── Analytics ───────────────────────────────────────────────────────────────\n\nmodel Analytics {\n  id            String   @id @default(uuid())\n  storeId       String\n  date          DateTime @db.Date\n  views         Int      @default(0)\n  visitors      Int      @default(0)\n  orders        Int      @default(0)\n  revenue       Float    @default(0)\n  conversions   Float    @default(0)\n  avgOrderValue Float    @default(0)\n  newCustomers  Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, date])\n  @@index([storeId])\n  @@map(\"analytics\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\n\n// ─── Support Ticket ──────────────────────────────────────────────────────────\n\nmodel SupportTicket {\n  id          String        @id @default(uuid())\n  userId      String\n  subject     String\n  message     String\n  status      SupportStatus @default(OPEN)\n  priority    Priority      @default(MEDIUM)\n  adminReply  String?\n  resolvedAt  DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  user        User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replies     TicketReply[]\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketReply {\n  id        String        @id @default(uuid())\n  ticketId  String\n  senderId  String\n  isAdmin   Boolean       @default(false)\n  message   String\n  createdAt DateTime      @default(now())\n\n  ticket    SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId])\n  @@map(\"ticket_replies\")\n}\n\n// ─── Platform Settings ───────────────────────────────────────────────────────\n\nmodel PlatformSettings {\n  id                  String   @id @default(\"singleton\")\n  platformFeePercent  Float    @default(10)\n  starterPrice        Float    @default(9)\n  proPrice            Float    @default(29)\n  advancedPrice       Float    @default(79)\n  maintenanceMode     Boolean  @default(false)\n  allowRegistration   Boolean  @default(true)\n  maxStoresPerOwner   Json     @default(\"{\\\"STARTER\\\":1,\\\"PRO\\\":3,\\\"ADVANCED\\\":999}\")\n  maxProductsPerStore Json     @default(\"{\\\"STARTER\\\":50,\\\"PRO\\\":500,\\\"ADVANCED\\\":999999}\")\n  smtpConfig          Json?\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\n// ─── Notification ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  type      String   @default(\"info\")\n  read      Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([read])\n  @@map(\"notifications\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  userId      String?\n  action      String\n  entity      String\n  entityId    String?\n  oldValues   Json?\n  newValues   Json?\n  ipAddress   String?\n  userAgent   String?\n  level       LogLevel @default(INFO)\n  createdAt   DateTime @default(now())\n\n  user        User?    @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([entity])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─── Error Log ───────────────────────────────────────────────────────────────\n\nmodel ErrorLog {\n  id          String   @id @default(uuid())\n  message     String\n  stack       String?\n  path        String?\n  method      String?\n  statusCode  Int?\n  userId      String?\n  ipAddress   String?\n  resolved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([resolved])\n  @@index([createdAt])\n  @@map(\"error_logs\")\n}\n\n// ─── Coupon ──────────────────────────────────────────────────────────────────\n\nmodel Coupon {\n  id            String    @id @default(uuid())\n  storeId       String\n  code          String\n  type          String    // PERCENTAGE | FIXED\n  discountType  String?   // alias for type\n  discountValue Float     @default(0)\n  value         Float\n  minOrderValue Float     @default(0)\n  maxUses       Int?\n  usageLimit    Int?\n  usedCount     Int       @default(0)\n  isActive      Boolean   @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  store         Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"coupons\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\nmodel ShippingZone {\n  id            String   @id @default(uuid())\n  storeId       String\n  name          String\n  countries     String[]\n  shippingRate  Float    @default(0)\n  freeThreshold Float?\n  estimatedDays String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"shipping_zones\")\n}\n\n// ─── Review ──────────────────────────────────────────────────────────────────\n\nmodel Review {\n  id         String   @id @default(uuid())\n  storeId    String\n  productId  String\n  name       String\n  email      String\n  rating     Int      // 1-5\n  title      String?\n  body       String\n  photos     String[] // array of image URLs\n  approved   Boolean  @default(false)\n  featured   Boolean  @default(false)\n  helpful    Int      @default(0)\n  verified   Boolean  @default(false)\n  orderId    String?  // set if from verified purchase\n  replyBody  String?  // store owner reply\n  repliedAt  DateTime?\n  source     String?  // \"email\" | \"in-app\" | \"import\"\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  store   Store   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@index([storeId])\n  @@map(\"reviews\")\n}\n\n// ─── Abandoned Cart ───────────────────────────────────────────────────────────\n\nmodel AbandonedCart {\n  id            String   @id @default(uuid())\n  storeId       String\n  email         String\n  name          String?\n  items         Json     // CartItem[]\n  total         Float\n  currency      String   @default(\"USD\")\n  token         String   @unique @default(uuid())  // recovery link token\n  recovered     Boolean  @default(false)\n  emailSent     Boolean  @default(false)\n  emailSentAt   DateTime?\n  recoveredAt   DateTime?\n  reminderCount Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([email])\n  @@index([token])\n  @@index([recovered, emailSent])\n  @@map(\"abandoned_carts\")\n}\n\n// ─── Supplier ─────────────────────────────────────────────────────────────────\n\nmodel Supplier {\n  id           String       @id @default(uuid())\n  storeId      String\n  name         String\n  type         SupplierType @default(MANUAL)\n  websiteUrl   String?\n  apiKey       String?\n  apiSecret    String?\n  contactEmail String?\n  contactName  String?\n  notes        String?\n  isActive     Boolean      @default(true)\n  autoFulfill  Boolean      @default(false)  // auto-forward orders when PROCESSING\n  fulfillEmail String?                        // email to send order details to\n  webhookUrl   String?                        // POST order JSON here on new order\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  store            Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  products         SupplierProduct[]\n  fulfillmentOrders FulfillmentOrder[]\n\n  @@index([storeId])\n  @@map(\"suppliers\")\n}\n\nmodel SupplierProduct {\n  id              String   @id @default(uuid())\n  supplierId      String\n  productId       String\n  supplierSku     String?             // SKU in supplier's system\n  supplierUrl     String?             // original product URL (e.g. AliExpress)\n  supplierPrice   Float?              // cost from supplier (in supplier's currency)\n  supplierCurrency String  @default(\"USD\")\n  processingDays  Int?                // how many days to process\n  shippingDays    Int?                // estimated shipping\n  lastSynced      DateTime?\n  stockStatus     String?             // \"IN_STOCK\" | \"LOW_STOCK\" | \"OUT_OF_STOCK\"\n  priority        Int      @default(1)  // 1 = primary, higher = fallback\n  isActive        Boolean  @default(true)\n  notes           String?             // internal notes\n  createdAt       DateTime @default(now())\n\n  supplier  Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([supplierId, productId])\n  @@index([productId])\n  @@map(\"supplier_products\")\n}\n\nmodel FulfillmentOrder {\n  id          String            @id @default(uuid())\n  orderId     String\n  supplierId  String\n  storeId     String\n  status      FulfillmentStatus @default(PENDING)\n  sentAt      DateTime?\n  confirmedAt DateTime?\n  notes       String?\n  supplierRef String?           // reference/tracking from supplier\n  method      String?           // \"EMAIL\" | \"WEBHOOK\" | \"MANUAL\"\n  payload     Json?             // what was sent to supplier\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n  store    Store    @relation(fields: [storeId],    references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([supplierId])\n  @@index([storeId])\n  @@map(\"fulfillment_orders\")\n}\n\n\nenum SupplierType {\n  MANUAL\n  ALIEXPRESS\n  CSV\n  WEBHOOK\n}\n\nenum FulfillmentStatus {\n  PENDING\n  SENT\n  CONFIRMED\n  SHIPPED\n  FAILED\n}\n\n\n// ─── Discount Engine ─────────────────────────────────────────────────────────\n\nmodel Discount {\n  id          String       @id @default(uuid())\n  storeId     String\n  name        String\n  description String?\n  type        DiscountType\n  status      DiscountStatus @default(ACTIVE)\n  priority    Int          @default(0)   // higher = applied first\n  stackable   Boolean      @default(false)\n\n  // Trigger conditions\n  minOrderValue    Float?\n  minQuantity      Int?\n  customerTag      String?  // e.g. \"VIP\", \"wholesale\"\n  productIds       String[] // empty = all products\n  collectionIds    String[]\n  firstOrderOnly   Boolean  @default(false)\n\n  // Value / Action\n  valueType   DiscountValueType\n  value       Float             // %, fixed $, or new price\n  maxDiscount Float?            // cap on percentage discounts\n  freeShipping Boolean          @default(false)\n\n  // BOGO fields\n  bogoRequiredQty  Int?         // buy X\n  bogoGetQty       Int?         // get Y\n  bogoPctOff       Float?       // discount on the free item (100 = fully free)\n\n  // Tiered pricing (JSON array of {qty, pct})\n  tiers       Json?            // [{minQty:2,discount:10},{minQty:5,discount:20}]\n\n  // Flash sale\n  flashSaleEndsAt DateTime?\n  flashSaleStartsAt DateTime?\n\n  // Usage limits\n  maxUses       Int?\n  maxUsesPerCustomer Int?\n  usedCount     Int       @default(0)\n\n  // Validity\n  startsAt   DateTime?\n  expiresAt  DateTime?\n  isAutomatic Boolean   @default(false) // no code needed\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store  Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  usages DiscountUsage[]\n\n  @@index([storeId])\n  @@map(\"discounts\")\n}\n\nmodel DiscountUsage {\n  id          String   @id @default(uuid())\n  discountId  String\n  orderId     String\n  customerId  String?\n  amountSaved Float\n  appliedAt   DateTime @default(now())\n\n  discount Discount @relation(fields: [discountId], references: [id], onDelete: Cascade)\n\n  @@index([discountId])\n  @@index([orderId])\n  @@map(\"discount_usages\")\n}\n\nenum DiscountType {\n  AUTOMATIC     // applies automatically at checkout\n  BOGO          // buy X get Y\n  TIERED        // volume tiers\n  FLASH_SALE    // time-limited\n  PERCENTAGE    // classic % off\n  FIXED         // fixed $ off\n  FREE_SHIPPING // free shipping\n  BUNDLE        // spend X get Y\n}\n\nenum DiscountStatus {\n  ACTIVE\n  PAUSED\n  EXPIRED\n  SCHEDULED\n}\n\nenum DiscountValueType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  NEW_PRICE\n  FREE\n}\n\n// ─── Referral & Affiliate System ─────────────────────────────────────────────\n\nmodel Affiliate {\n  id          String          @id @default(uuid())\n  storeId     String\n  name        String\n  email       String\n  code        String          // unique referral code\n  status      AffiliateStatus @default(PENDING)\n  commissionPct Float         @default(10)  // % of order value\n  commissionFlat Float?       // flat $ per sale (override)\n  payoutMethod  String?       // \"paypal\" | \"bank\" | \"store_credit\"\n  payoutDetails Json?         // encrypted payout info\n  totalEarned   Float         @default(0)\n  totalPaid     Float         @default(0)\n  totalClicks   Int           @default(0)\n  totalOrders   Int           @default(0)\n  notes         String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  store     Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  referrals ReferralConversion[]\n  payouts   AffiliatePayout[]\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"affiliates\")\n}\n\nmodel ReferralConversion {\n  id          String   @id @default(uuid())\n  affiliateId String\n  orderId     String\n  storeId     String\n  orderValue  Float\n  commission  Float\n  status      String   @default(\"PENDING\")  // PENDING | APPROVED | PAID | REJECTED\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@index([orderId])\n  @@map(\"referral_conversions\")\n}\n\nmodel AffiliatePayout {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  amount      Float\n  method      String\n  status      String   @default(\"PENDING\")  // PENDING | SENT | FAILED\n  reference   String?\n  note        String?\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@map(\"affiliate_payouts\")\n}\n\n// Affiliate click tracking\nmodel ReferralClick {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  ip          String?\n  userAgent   String?\n  page        String?\n  converted   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([affiliateId])\n  @@map(\"referral_clicks\")\n}\n\nenum AffiliateStatus {\n  PENDING\n  ACTIVE\n  PAUSED\n  SUSPENDED\n}\n\n// ─── Web Push Subscriptions ──────────────────────────────────────────────────\n\nmodel PushSubscription {\n  id       String   @id @default(uuid())\n  userId   String\n  endpoint String   @unique\n  p256dh   String   // public key\n  auth     String   // auth secret\n  deviceName String?  // e.g. \"Chrome on iPhone\"\n  isActive Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\n// ─── Refund & Dispute ────────────────────────────────────────────────────────\n\nenum RefundStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSED\n}\n\nenum RefundReason {\n  DAMAGED\n  NOT_RECEIVED\n  WRONG_ITEM\n  NOT_AS_DESCRIBED\n  CHANGED_MIND\n  OTHER\n}\n\nmodel Refund {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  amount      Float\n  reason      RefundReason\n  description String?\n  status      RefundStatus @default(PENDING)\n  gatewayRef  String?      // gateway refund ID\n  processedAt DateTime?\n  adminNote   String?\n  photos      String[]     @default([])\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"refunds\")\n}\n\n// ─── Customer Accounts ───────────────────────────────────────────────────────\n\nmodel CustomerAccount {\n  id            String    @id @default(uuid())\n  storeId       String\n  email         String\n  name          String\n  phone         String?\n  passwordHash  String\n  emailVerified Boolean   @default(false)\n  verifyToken   String?\n  resetToken    String?\n  resetExpiry   DateTime?\n  refreshToken  String?\n  defaultAddress Json?\n  savedAddresses Json[]   @default([])\n  wishlist       String[] @default([]) // productIds\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"customer_accounts\")\n}\n\n// ─── Wishlist ────────────────────────────────────────────────────────────────\n\nmodel Wishlist {\n  id         String   @id @default(uuid())\n  storeId    String\n  email      String\n  productId  String\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, email, productId])\n  @@index([storeId, email])\n  @@map(\"wishlists\")\n}\n\n// ─── Gift Card ───────────────────────────────────────────────────────────────\n\nmodel GiftCard {\n  id          String    @id @default(uuid())\n  storeId     String\n  code        String    @unique\n  balance     Float\n  initialAmount Float\n  currency    String    @default(\"USD\")\n  isActive    Boolean   @default(true)\n  purchasedBy String?   // email\n  assignedTo  String?   // email\n  expiresAt   DateTime?\n  note        String?\n  redeemedAmount Float  @default(0)\n  usages      GiftCardUsage[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([code])\n  @@map(\"gift_cards\")\n}\n\nmodel GiftCardUsage {\n  id         String   @id @default(uuid())\n  giftCardId String\n  orderId    String\n  amount     Float\n  createdAt  DateTime @default(now())\n\n  giftCard   GiftCard @relation(fields: [giftCardId], references: [id], onDelete: Cascade)\n\n  @@index([giftCardId])\n  @@map(\"gift_card_usages\")\n}\n\n// ─── Funnel Analytics ────────────────────────────────────────────────────────\n\nmodel FunnelEvent {\n  id        String   @id @default(uuid())\n  storeId   String\n  sessionId String\n  event     String   // \"view\" | \"add_to_cart\" | \"checkout_start\" | \"purchase\"\n  productId String?\n  orderId   String?\n  value     Float?\n  meta      Json?\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([storeId])\n  @@index([sessionId])\n  @@index([event])\n  @@index([createdAt])\n  @@map(\"funnel_events\")\n}\n\n// ─── UTM / Traffic Source ────────────────────────────────────────────────────\n\nmodel UtmSession {\n  id         String   @id @default(uuid())\n  storeId    String\n  sessionId  String\n  source     String?\n  medium     String?\n  campaign   String?\n  term       String?\n  content    String?\n  landingPage String?\n  referrer   String?\n  converted  Boolean  @default(false)\n  orderId    String?\n  orderValue Float?\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, sessionId])\n  @@index([storeId])\n  @@index([source])\n  @@map(\"utm_sessions\")\n}\n\n// ─── API Keys (store owner) ─────────────────────────────────────────────────\n\nmodel ApiKey {\n  id          String    @id @default(uuid())\n  storeId     String\n  name        String\n  keyHash     String    @unique  // SHA-256 of actual key\n  keyPrefix   String             // first 8 chars for display\n  permissions String[]  @default([]) // [\"orders:read\",\"products:write\",...]\n  isActive    Boolean   @default(true)\n  lastUsedAt  DateTime?\n  expiresAt   DateTime?\n  createdAt   DateTime  @default(now())\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([keyHash])\n  @@map(\"api_keys\")\n}\n\n// ─── Store Backup ────────────────────────────────────────────────────────────\n\nmodel StoreBackup {\n  id        String   @id @default(uuid())\n  storeId   String\n  fileName  String\n  fileUrl   String\n  fileSize  Int?     // bytes\n  status    String   @default(\"PENDING\") // PENDING | READY | FAILED\n  createdAt DateTime @default(now())\n\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"store_backups\")\n}\n\n// ─── Outgoing Webhooks (store owner) ────────────────────────────────────────\n\nmodel StoreWebhook {\n  id        String   @id @default(uuid())\n  storeId   String\n  url       String\n  events    String[] // [\"order.created\",\"order.paid\",\"product.updated\",...]\n  secret    String\n  isActive  Boolean  @default(true)\n  lastFiredAt DateTime?\n  failCount  Int     @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store      Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  deliveries WebhookDelivery[]\n\n  @@index([storeId])\n  @@map(\"store_webhooks\")\n}\n\nmodel WebhookDelivery {\n  id         String   @id @default(uuid())\n  webhookId  String\n  event      String\n  payload    Json\n  statusCode Int?\n  response   String?\n  success    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  webhook StoreWebhook @relation(fields: [webhookId], references: [id], onDelete: Cascade)\n\n  @@index([webhookId])\n  @@map(\"webhook_deliveries\")\n}\n\n// ─── Flash Sale ──────────────────────────────────────────────────────────────\n\nmodel FlashSale {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  discountPct Float\n  productIds  String[]\n  startsAt    DateTime\n  endsAt      DateTime\n  isActive    Boolean  @default(true)\n  bannerText  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  store       Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"flash_sales\")\n}\n\n// ─── Return / RMA ────────────────────────────────────────────────────────────\n\nenum ReturnStatus {\n  REQUESTED\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nmodel ReturnRequest {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  customerEmail String\n  reason      String\n  description String?\n  photos      String[]     @default([])\n  status      ReturnStatus @default(REQUESTED)\n  trackingNumber String?\n  adminNote   String?\n  resolvedAt  DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"return_requests\")\n}\n\n// ─── Subscription Products ───────────────────────────────────────────────────\n\nmodel ProductSubscription {\n  id            String   @id @default(uuid())\n  storeId       String\n  productId     String\n  customerEmail String\n  interval      String   // \"weekly\" | \"monthly\" | \"quarterly\"\n  intervalCount Int      @default(1)\n  price         Float\n  currency      String   @default(\"USD\")\n  discount      Float    @default(0) // % off for subscribing\n  status        String   @default(\"ACTIVE\") // ACTIVE | PAUSED | CANCELLED\n  nextBillingAt DateTime\n  stripeSubId   String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([storeId])\n  @@index([customerEmail])\n  @@map(\"product_subscriptions\")\n}\n\n// ─── Cohort Analytics ────────────────────────────────────────────────────────\n\nmodel CohortData {\n  id        String   @id @default(uuid())\n  storeId   String\n  cohortMonth String  // \"2025-01\"\n  totalCustomers Int @default(0)\n  day30Return    Int @default(0)\n  day60Return    Int @default(0)\n  day90Return    Int @default(0)\n  calculatedAt   DateTime @default(now())\n\n  @@unique([storeId, cohortMonth])\n  @@index([storeId])\n  @@map(\"cohort_data\")\n}\n\n// ─── KAI Chat History ─────────────────────────────────────────────────────────\n\nmodel KaiConversation {\n  storeId   String?\n  id        String       @id @default(uuid())\n  userId    String\n  title     String       @default(\"New Chat\")\n  archived  Boolean      @default(false)\n  pinned    Boolean      @default(false)\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n  messages  KaiMessage[]\n\n  user      User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"kai_conversations\")\n}\n\nmodel KaiMessage {\n  id             String          @id @default(uuid())\n  conversationId String\n  role           String          // \"user\" | \"assistant\"\n  content        String          @db.Text\n  action         String?\n  metadata       Json?\n  createdAt      DateTime        @default(now())\n\n  conversation   KaiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId])\n  @@map(\"kai_messages\")\n}\n\n\nmodel StoreIntegration {\n  id           String    @id @default(cuid())\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  provider     String\n  email        String?\n  password     String?\n  accessToken  String?   @db.Text\n  refreshToken String?\n  expiresAt    DateTime?\n  isActive     Boolean   @default(true)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([storeId, provider], name: \"storeId_provider\")\n  @@index([storeId])\n}\n\nmodel WaitlistEntry {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  whatsapp     String?\n  spotNumber   Int      @unique\n  referralCode String   @unique\n  referredBy   String?\n  source       String?\n  ipHash       String?\n  confirmed    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([email])\n  @@index([referralCode])\n  @@index([spotNumber])\n}\n\nmodel Bundle {\n  id              String   @id @default(uuid())\n  storeId         String\n  store           Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  name            String\n  productIds      String[]\n  discountPercent Float    @default(10)\n  bundlePrice     Float?\n  originalPrice   Float?\n  active          Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel GroupBuy {\n  id              String        @id @default(uuid())\n  storeId         String\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id])\n  title           String\n  description     String?\n  groupPrice      Float\n  originalPrice   Float\n  minMembers      Int\n  endsAt          DateTime\n  active          Boolean       @default(true)\n  members         GroupBuyMember[]\n  createdAt       DateTime      @default(now())\n}\n\nmodel GroupBuyMember {\n  id          String   @id @default(uuid())\n  groupBuyId  String\n  groupBuy    GroupBuy @relation(fields: [groupBuyId], references: [id], onDelete: Cascade)\n  name        String\n  email       String\n  paid        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\nmodel Milestone {\n  id        String   @id @default(uuid())\n  storeId   String\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  type      String\n  title     String\n  message   String\n  cta       Json?\n  seen      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel ContactMessage {\n  id        String   @id @default(uuid())\n  name      String\n  email     String\n  subject   String   @default(\"general\")\n  message   String\n  status    String   @default(\"new\")\n  createdAt DateTime @default(now())\n}\n\nmodel Referral {\n  id          String   @id @default(uuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code        String   @unique\n  clicks      Int      @default(0)\n  signups     Int      @default(0)\n  conversions Int      @default(0)\n  earned      Float    @default(0)\n  pending     Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n\n\n\n\n\n\n\n\n\n\nmodel RefreshToken {\n  id          String    @id @default(uuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token       String    @unique\n  expiresAt   DateTime\n  revokedAt   DateTime?\n  ipAddress   String?\n  userAgent   String?\n  createdAt   DateTime  @default(now())\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel KaiMemory {\n  id         String   @id @default(uuid())\n  userId     String?\n  storeId    String?\n  key        String\n  value      String\n  category              String   @default(\"general\")\n  confidence            Float    @default(1.0)\n  sourceConversationId  String?\n  lastUsed   DateTime @default(now())\n  ttl        DateTime?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  @@unique([userId, key])\n  @@unique([storeId, key], name: \"storeId_key\")\n  @@map(\"kai_memories\")\n}\n\nmodel KaiGoal {\n  id           String   @id @default(uuid())\n  userId       String\n  storeId      String\n  title        String\n  description  String?\n  target       Float?\n  targetValue  Float?\n  current      Float    @default(0)\n  currentValue Float    @default(0)\n  unit         String   @default(\"NGN\")\n  status       String   @default(\"active\")\n  deadline     DateTime?\n  achieved     Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  @@map(\"kai_goals\")\n}\n\nmodel KaiMarketCache {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  data        Json\n  category    String   @default(\"general\")\n  expiresAt   DateTime\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_market_cache\")\n}\n\nmodel KaiPulseAlert {\n  id        String   @id @default(uuid())\n  storeId         String\n  userId          String?\n  type            String\n  title           String\n  message         String\n  data            Json?\n  read            Boolean  @default(false)\n  priority        String   @default(\"normal\")\n  severity        String   @default(\"info\")\n  actionable      Boolean  @default(false)\n  suggestedPrompt String?\n  createdAt  DateTime @default(now())\n  @@index([storeId])\n  @@index([userId])\n  @@map(\"kai_pulse_alerts\")\n}\n\nmodel KaiMorningBrief {\n  id                String   @id @default(uuid())\n  userId            String\n  storeId           String\n  content           String\n  date              DateTime @default(now())\n  delivered         Boolean  @default(false)\n  topOpportunity    String?\n  revenueLastNight  Float    @default(0)\n  ordersLastNight   Int      @default(0)\n  urgentAction      String?\n  @@unique([storeId, date], name: \"storeId_date\")\n  @@map(\"kai_morning_briefs\")\n}\n\nmodel KaiBrandVoice {\n  id         String   @id @default(uuid())\n  storeId    String   @unique\n  tone       String   @default(\"friendly\")\n  style      String   @default(\"conversational\")\n  keywords   String[] @default([])\n  avoidWords  String[] @default([])\n  examples    String[] @default([])\n  usesEmojis     Boolean  @default(true)\n  language       String   @default(\"en\")\n  sentenceLength String   @default(\"medium\")\n  sampleContent  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_brand_voices\")\n}\n\nmodel KaiSkill {\n  id          String   @id @default(uuid())\n  userId      String\n  storeId     String?\n  name        String\n  description String?\n  prompt      String\n  icon        String?  @default(\"⚡\")\n  useCount    Int      @default(0)\n  usageCount  Int      @default(0)\n  active      Boolean  @default(true)\n  isGlobal    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([userId])\n  @@map(\"kai_skills\")\n}\n\nmodel LoyaltyAccount {\n  id           String   @id @default(uuid())\n  storeId      String\n  customerId   String\n  points       Int      @default(0)\n  totalEarned  Int      @default(0)\n  totalSpent     Int      @default(0)\n  totalRedeemed  Int      @default(0)\n  tier           String   @default(\"bronze\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  transactions   LoyaltyTransaction[]\n  @@unique([storeId, customerId])\n  @@map(\"loyalty_accounts\")\n}\n\nmodel ReviewRequest {\n  id         String   @id @default(uuid())\n  orderId    String   @unique\n  storeId    String\n  customerId String?\n  email      String   @default(\"\")\n  sentAt     DateTime?\n  responded  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  @@map(\"review_requests\")\n}\n\nmodel ProfitProtectionRule {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  minMargin   Float    @default(20)\n  action      String   @default(\"alert\")\n  active      Boolean  @default(true)\n  isActive    Boolean  @default(true)\n  trigger     String   @default(\"margin_drop\")\n  threshold   Float    @default(20)\n  actionValue Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([storeId])\n  @@map(\"profit_protection_rules\")\n}\n\nmodel LoyaltyTransaction {\n  id          String   @id @default(uuid())\n  accountId   String\n  account     LoyaltyAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)\n  type        String   // earn | redeem\n  points      Int\n  orderId     String?\n  description String?\n  createdAt   DateTime @default(now())\n  @@index([accountId])\n  @@map(\"loyalty_transactions\")\n}\n\nmodel WhatsappBroadcast {\n  id             String    @id @default(uuid())\n  storeId        String\n  message        String\n  recipients     Int       @default(0)\n  recipientCount Int       @default(0)\n  sent           Int       @default(0)\n  sentCount      Int       @default(0)\n  failed         Int       @default(0)\n  status         String    @default(\"pending\")\n  scheduledAt    DateTime?\n  sentAt         DateTime?\n  store          Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  @@index([storeId])\n  @@map(\"whatsapp_broadcasts\")\n}\n\nmodel KaiActionLog {\n  id             String   @id @default(uuid())\n  storeId        String\n  conversationId String?\n  actionType     String\n  payload        Json?\n  approved       Boolean  @default(false)\n  executed       Boolean  @default(false)\n  result         Json?\n  createdAt      DateTime @default(now())\n  @@index([storeId])\n  @@map(\"kai_action_logs\")\n}\n"};
